  const clone = (value) => JSON.parse(JSON.stringify(value));
  const uid = (prefix='id') => `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2,7)}`;
  const normalize = (value='') => String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  const esc = (value='') => String(value).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
  const parseMoney = value => window.CurrencyBRL?.parse ? window.CurrencyBRL.parse(value) : (Number(value)||0);
  const money = (value=0) => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(parseMoney(value));
  const shortMoney = (value=0) => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',notation:'compact',maximumFractionDigits:1}).format(parseMoney(value));
