    $('#globalSearchBtn').addEventListener('click',openSearch); $('#closeSearchBtn').addEventListener('click',closeSearch); $('#globalSearchInput').addEventListener('input',renderSearchResults);
    $('#mobileMenuBtn').addEventListener('click',openDrawer); $('#closeDrawerBtn').addEventListener('click',closeDrawer); $('#mobileDrawerBackdrop').addEventListener('click',closeDrawer);
    $('#closeModalBtn').addEventListener('click',closeModal); $('#modalBackdrop').addEventListener('click',event=>{if(event.target===event.currentTarget)closeModal()});
