    {id:'campaign_invite',title:'Campanha',type:'Carta de convite',image:'assets/images/evangelizacao/modelo-banner.jpg',headline:'Campanha de fé e oração',subtitle:'Noites de clamor, palavra e renovação espiritual',message:'Participe desta campanha e convide alguém que precisa de esperança.',verse:'Clama a mim, e responder-te-ei. — Jeremias 33:3'},
    {id:'couples_meeting',title:'Encontro de casais',type:'Carta de convite',image:'assets/images/evangelizacao/modelo-convite.png',headline:'Encontro de casais',subtitle:'Uma noite para fortalecer o amor, a fé e a família',message:'Preparamos um encontro especial para casais, com palavra e comunhão.',verse:'Assim, eles já não são dois, mas uma só carne. — Mateus 19:6'}
