  function openEvangelizationLibrary(){
    const saved=(db.evangelismDesigns||[]);
    openModal({eyebrow:'DOCUMENTOS · EVANGELIZAÇÃO',title:'Modelos para impressão',subtitle:'Escolha um modelo pronto, edite os dados e gere a impressão.',wide:true,body:`<div class="evangelization-template-grid">${EVANGELIZATION_TEMPLATES.map(t=>`<article class="evangelization-template-card"><img src="${t.image}" alt="${esc(t.title)}"><div><small>${esc(t.type)}</small><h3>${esc(t.title)}</h3><button class="btn btn-primary btn-small" data-action="evangelization-new" data-id="${t.id}">Usar modelo</button></div></article>`).join('')}</div><div class="panel-head evangelization-saved-head"><div><span class="panel-kicker">ARQUIVOS SALVOS</span><h2>Materiais editados</h2></div></div>${saved.length?`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Protocolo</th><th>Material</th><th>Evento</th><th>Status</th><th>Ações</th></tr></thead><tbody>${saved.map(x=>`<tr><td><strong>${esc(x.protocol)}</strong></td><td>${esc(evangelismTemplate(x.templateId).title)}</td><td>${esc(x.headline)}</td><td>${badge(x.status)}</td><td><div class="table-actions"><button data-action="evangelization-edit" data-id="${x.id}">${icon('i-edit')}</button><button data-action="evangelization-print" data-id="${x.id}">${icon('i-print')}</button><button data-action="evangelization-delete" data-id="${x.id}">${icon('i-trash')}</button></div></td></tr>`).join('')}</tbody></table></div>`:emptyState('i-megaphone','Nenhum material salvo','Escolha um dos modelos acima para criar o primeiro material.')}`});
  }
  function openEvangelismDesign(templateId,id=''){
    const template=evangelismTemplate(templateId),x=(db.evangelismDesigns||[]).find(item=>item.id===id)||{};
    openModal({eyebrow:'EVANGELIZAÇÃO',title:x.id?'Editar material':template.title,subtitle:'A arte e todos os textos podem ser personalizados antes da impressão.',wide:true,body:`<form data-form="evangelism-design" data-id="${x.id||''}" class="form-grid"><input type="hidden" name="templateId" value="${template.id}">${imageUploadField('artwork','Arte principal',x.artwork||template.image,'wide','Use o editor livre para retirar bordas pretas e definir exatamente o enquadramento.')}${textField('protocol','Protocolo',x.protocol||nextEvangelismProtocol(),'text','required')}${selectField('status','Status',['Rascunho','Pronto para impressão','Arquivado'],x.status||'Rascunho')}${textField('headline','Título principal',x.headline||template.headline,'text','required')}${textField('subtitle','Subtítulo',x.subtitle||template.subtitle)}${textField('eventDate','Data',x.eventDate||todayISO(),'date')}${textField('eventTime','Horário',x.eventTime||'19:00','time')}${textField('location','Local',x.location||activeChurch().address||activeChurch().name)}${textField('speaker','Preletor / responsável',x.speaker||activeChurch().pastor||'')}${textField('contact','Contato',x.contact||activeChurch().phone||'')}<label class="field span-2"><span>Versículo</span><textarea name="verse">${esc(x.verse||template.verse)}</textarea></label><label class="field span-2"><span>Mensagem do convite</span><textarea name="message">${esc(x.message||template.message)}</textarea></label>${modalActions()}</form>`});
  }
  function printEvangelismDesign(id){
    const x=(db.evangelismDesigns||[]).find(item=>item.id===id);if(!x)return;const t=evangelismTemplate(x.templateId),w=window.open('','_blank','width=900,height=1000');if(!w){showToast('Janela bloqueada','Permita pop-ups para imprimir.','error');return;}w.document.write(`<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><title>${esc(x.headline)}</title><style>@page{size:A4;margin:0}*{box-sizing:border-box}body{margin:0;background:#fff;font-family:Arial,sans-serif;-webkit-print-color-adjust:exact;print-color-adjust:exact}.sheet{width:210mm;height:297mm;position:relative;overflow:hidden;background:#07111b;color:#fff}.art{position:absolute;inset:0;background:url('${esc(x.artwork||t.image)}') center/cover no-repeat}.shade{position:absolute;inset:0;background:linear-gradient(180deg,rgba(0,0,0,.08),rgba(0,0,0,.78))}.content{position:absolute;left:18mm;right:18mm;bottom:20mm;padding:14mm;border:1px solid rgba(255,255,255,.45);border-radius:7mm;background:rgba(3,9,15,.74)}h1{font-family:Georgia,serif;font-size:31pt;line-height:1.02;margin:0 0 4mm}h2{font-size:15pt;color:#f1cf78;margin:0 0 6mm}p,blockquote{font-size:11.5pt;line-height:1.5}blockquote{border-left:1.2mm solid #d4a743;padding-left:4mm;margin:5mm 0}.info{display:grid;grid-template-columns:1fr 1fr;gap:5mm;margin-top:6mm}.info div{border-top:.7mm solid #d4a743;padding-top:2mm}.info small,.info b{display:block}.info small{font-size:7pt;letter-spacing:1px;color:#f1cf78}.info b{font-size:10pt}</style></head><body><article class="sheet"><div class="art"></div><div class="shade"></div><section class="content"><small>${esc(activeChurch().name)}</small><h1>${esc(x.headline)}</h1><h2>${esc(x.subtitle)}</h2><p>${esc(x.message)}</p><blockquote>${esc(x.verse)}</blockquote><div class="info"><div><small>DATA E HORÁRIO</small><b>${dateBR(x.eventDate)} · ${esc(x.eventTime)}</b></div><div><small>LOCAL</small><b>${esc(x.location)}</b></div><div><small>RESPONSÁVEL</small><b>${esc(x.speaker)}</b></div><div><small>CONTATO</small><b>${esc(x.contact)}</b></div></div></section></article><script>addEventListener('load',()=>print())<\/script></body></html>`);w.document.close();
  }


  function documentTemplate(id){return DOCUMENT_LIBRARY_TEMPLATES.find(template=>template.id===id)||DOCUMENT_LIBRARY_TEMPLATES[0];}
  function memberDocumentCount(memberId){return db.issuedDocuments.filter(document=>document.memberId===memberId||document.partnerMemberId===memberId).length;}
  function nextDocumentProtocol(templateId){const template=documentTemplate(templateId),year=new Date().getFullYear(),used=db.issuedDocuments.filter(document=>document.templateId===templateId&&String(document.issueDate||'').startsWith(String(year))).length+1;return `${template.code}-${year}-${String(used).padStart(4,'0')}`;}
  function libraryActivityRows(memberId=''){
    const rows=[];
    db.issuedDocuments.forEach(x=>{if(!memberId||x.memberId===memberId||x.partnerMemberId===memberId)rows.push({date:x.issueDate,type:'Documento',title:documentTemplate(x.templateId).title,detail:x.protocol,memberId:x.memberId,icon:'i-doc'});});
    db.contributions.forEach(x=>{if(x.memberId&&(!memberId||x.memberId===memberId))rows.push({date:(byId('transactions',x.transactionId)?.date||todayISO()),type:'Contribuição',title:x.type,detail:money(x.amount),memberId:x.memberId,icon:'i-hand'});});
    db.shifts.forEach(x=>{if(!memberId||x.memberId===memberId)rows.push({date:x.date,type:'Escala',title:x.role,detail:byId('teams',x.teamId)?.name||'Equipe',memberId:x.memberId,icon:'i-checklist'});});
    (db.memberTransfers||[]).forEach(x=>{if(!memberId||x.memberId===memberId)rows.push({date:x.date,type:'Transferência',title:x.direction==='saida'?'Transferência de saída':'Recebimento de membro',detail:x.protocol,memberId:x.memberId,icon:'i-refresh'});});
    return rows.sort((a,b)=>String(b.date).localeCompare(String(a.date)));
  }
  function renderMemberActivity(){
    const memberId=state.memberId||'',rows=libraryActivityRows(memberId),member=byId('members',memberId);
    return `<div class="page">${pageTitle('HISTÓRICO INTEGRADO','Atividade de membro','Consulte em uma única linha do tempo as atividades, emissões e registros vinculados a cada pessoa.')}
      <div class="workspace"><div class="workspace-toolbar"><label class="field compact-field"><span>Membro</span><select data-member-activity-filter><option value="">Todos os membros</option>${db.members.map(m=>`<option value="${m.id}" ${m.id===memberId?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><strong>${rows.length} registro(s)</strong></div>
      ${member?`<div class="library-form-note">${icon('i-users')}<div><strong>${esc(member.name)}</strong><p>${esc(member.phone||'Sem telefone')} · ${esc(member.email||'Sem e-mail')}</p></div></div>`:''}
      <div class="data-table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Membro</th><th>Categoria</th><th>Atividade</th><th>Referência</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${dateBR(r.date)}</td><td>${esc(byId('members',r.memberId)?.name||'—')}</td><td>${badge(r.type)}</td><td><strong>${esc(r.title)}</strong></td><td>${esc(r.detail)}</td></tr>`).join('')}</tbody></table>${rows.length?'':emptyState('i-users','Sem atividades','Nenhuma atividade foi encontrada para o filtro selecionado.')}</div></div></div>`;
  }
  function renderMemberTransfers(){
    const rows=[...(db.memberTransfers||[])].sort((a,b)=>String(b.date).localeCompare(String(a.date)));
    return `<div class="page">${pageTitle('MOVIMENTAÇÃO DE MEMBRESIA','Transferência de membro','Registre entradas, saídas e cartas de transferência entre igrejas.',canWriteAdmin()?actionButton('new-member-transfer','Nova transferência','i-plus'):'')}
      <div class="metrics-grid">${metric('Transferências',rows.length,'i-refresh','Total registrado')}${metric('Em andamento',rows.filter(x=>x.status==='Em andamento').length,'i-calendar','Aguardando conclusão','gold')}${metric('Concluídas',rows.filter(x=>x.status==='Concluída').length,'i-check','Processos finalizados')}${metric('Recebimentos',rows.filter(x=>x.direction==='entrada').length,'i-users','Membros recebidos','navy')}</div>
      <div class="workspace"><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Protocolo</th><th>Membro</th><th>Movimento</th><th>Igreja relacionada</th><th>Data</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(x=>`<tr><td><strong>${esc(x.protocol)}</strong></td><td>${esc(byId('members',x.memberId)?.name||x.memberName||'—')}</td><td>${x.direction==='saida'?'Saída':'Entrada'}</td><td>${esc(x.otherChurch||'—')}</td><td>${dateBR(x.date)}</td><td>${badge(x.status)}</td><td><div class="table-actions"><button data-action="member-transfer-view" data-id="${x.id}" title="Visualizar">${icon('i-search')}</button><button data-action="member-transfer-print" data-id="${x.id}" title="Imprimir carta">${icon('i-print')}</button>${canWriteAdmin()?`<button data-action="member-transfer-edit" data-id="${x.id}" title="Editar">${icon('i-edit')}</button><button data-action="member-transfer-delete" data-id="${x.id}" title="Excluir">${icon('i-trash')}</button>`:''}</div></td></tr>`).join('')}</tbody></table>${rows.length?'':emptyState('i-refresh','Nenhuma transferência','Registre a primeira movimentação de membro.')}</div></div></div>`;
  }
  function renderFinancialArchive(){
    const rows=[...db.documents.filter(x=>['Contrato','Ofício','Licença'].includes(x.type)).map(x=>({date:x.date,title:x.title,ref:x.reference,type:x.type,status:x.status})),...db.reconciliations.map(x=>({date:x.date||x.closedAt,title:'Conciliação bancária',ref:x.id,type:'Bancário',status:x.status})),...db.approvals.map(x=>({date:x.requestedAt||x.decidedAt,title:x.description,ref:x.id,type:'Aprovação',status:x.status}))].sort((a,b)=>String(b.date).localeCompare(String(a.date)));
    return archiveTablePage('DOCUMENTOS FINANCEIROS','Documentos financeiros e bancários','Comprovantes, conciliações, contratos e aprovações financeiras.',rows,'i-bank');
  }
