  function archiveTablePage(kicker,title,text,rows,ico){return `<div class="page">${pageTitle(kicker,title,text)}<div class="metrics-grid">${metric('Documentos',rows.length,ico,'Registros disponíveis')}${metric('Emitidos / concluídos',rows.filter(x=>['Emitido','Concluído','Concluída','Conciliado','Fechado','Aprovado'].includes(x.status)).length,'i-check','Registros finalizados')}${metric('Em andamento',rows.filter(x=>['Em andamento','Rascunho','Aberto','Pendente'].includes(x.status)).length,'i-calendar','Demandas abertas','gold')}</div><div class="workspace"><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Documento</th><th>Categoria</th><th>Referência</th><th>Status</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dateBR(x.date)}</td><td><strong>${esc(x.title)}</strong></td><td>${esc(x.type)}</td><td>${esc(x.ref||'—')}</td><td>${badge(x.status||'Registrado')}</td></tr>`).join('')}</tbody></table>${rows.length?'':emptyState(ico,'Arquivo vazio','Os documentos aparecerão aqui conforme forem gerados nas demais áreas.')}</div></div></div>`;}
  function renderLibrary(){
    const tab=state.tab==='history'?'history':'models',query=normalize(state.query);
    const issued=[...db.issuedDocuments].filter(document=>{const member=byId('members',document.memberId),template=documentTemplate(document.templateId);return !query||normalize(`${document.protocol} ${member?.name||''} ${template.title} ${document.status}`).includes(query)}).sort((a,b)=>String(b.createdAt||b.issueDate).localeCompare(String(a.createdAt||a.issueDate)));
    const thisMonth=todayISO().slice(0,7),monthCount=db.issuedDocuments.filter(document=>String(document.issueDate||'').startsWith(thisMonth)).length;
    return `<div class="page">${pageTitle('MODELOS E EMISSÕES','Biblioteca','Gere crachás, certificados, declarações e cartas usando automaticamente os dados dos membros e da igreja.')}
      <div class="metrics-grid">${metric('Modelos disponíveis',DOCUMENT_LIBRARY_TEMPLATES.length,'i-library','Documentos prontos para emissão')}${metric('Documentos emitidos',db.issuedDocuments.length,'i-doc','Histórico desta igreja')}${metric('Emitidos neste mês',monthCount,'i-calendar','Protocolos gerados no mês','gold')}${metric('Membros documentados',new Set(db.issuedDocuments.map(document=>document.memberId).filter(Boolean)).size,'i-users','Pessoas com ao menos uma emissão','navy')}</div>
      <div class="workspace library-workspace"><div class="workspace-toolbar"><div class="segmented"><button data-filter-tab="models" class="${tab==='models'?'active':''}">Modelos</button><button data-filter-tab="history" class="${tab==='history'?'active':''}">Histórico de emissões</button></div>${tab==='history'?`<label class="search-field">${icon('i-search')}<input data-live-search value="${esc(state.query)}" placeholder="Buscar protocolo, pessoa ou documento"></label>`:''}</div>
      ${tab==='models'?`<div class="library-template-grid">${DOCUMENT_LIBRARY_TEMPLATES.map(template=>`<article class="library-template-card"><div class="library-template-top"><span class="library-template-icon">${icon(template.icon)}</span><span class="badge">${esc(template.category)}</span></div><h3>${esc(template.title)}</h3><p>${esc(template.description)}</p><div class="library-template-footer"><small>${db.issuedDocuments.filter(document=>document.templateId===template.id).length} emissão(ões)</small><button class="btn btn-primary btn-small" data-action="library-issue" data-id="${template.id}">${icon('i-plus')}Emitir</button></div></article>`).join('')}</div>`:`<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Protocolo</th><th>Documento</th><th>Pessoa</th><th>Emissão</th><th>Emitido por</th><th>Status</th><th>Ações</th></tr></thead><tbody>${issued.map(document=>{const member=byId('members',document.memberId),template=documentTemplate(document.templateId);return `<tr><td><strong>${esc(document.protocol)}</strong></td><td>${esc(template.title)}<small>${esc(template.category)}</small></td><td>${esc(member?.name||document.memberName||'—')}${document.partnerName?`<small>com ${esc(document.partnerName)}</small>`:''}</td><td>${dateBR(document.issueDate)}</td><td>${esc(document.issuedBy||'—')}</td><td>${badge(document.status||'Emitido')}</td><td><div class="table-actions"><button data-action="library-preview" data-id="${document.id}" title="Visualizar">${icon('i-search')}</button><button data-action="library-print" data-id="${document.id}" title="Imprimir">${icon('i-print')}</button>${canWriteAdmin()?`<button data-action="library-delete" data-id="${document.id}" title="Excluir">${icon('i-trash')}</button>`:''}</div></td></tr>`}).join('')}</tbody></table>${issued.length?'':emptyState('i-library','Nenhum documento emitido','Escolha um modelo para realizar a primeira emissão.')}</div>`}</div></div>`;
  }

