  function renderAdminSettingsPanel(){
    const tab=state.tab==='all'?'church':state.tab;
    if(tab==='users')return `<div class="panel-head"><div><span class="panel-kicker">LOGIN DO SISTEMA</span><h2>Usuários do sistema</h2></div>${actionButton('new-user','Novo usuário do sistema')}</div><div class="settings-list">${db.users.map(u=>`<div class="settings-item"><div><strong>${esc(u.name)}</strong><small>Login: <b>${esc(u.login||'—')}</b> · ${esc(u.email)} · ${esc(MANAGEMENT_ROLE_LABELS[managementRole(u)]||managementRole(u))} · ${canSeeAllChurches(u)?'Todas as igrejas':esc((db.churches.find(church=>(u.churchIds||[]).includes(church.id))||{}).name||'Sem igreja')} · ${u.areas.map(a=>AREA_LABELS[a]).join(' / ')}</small></div><div class="page-title-actions">${badge(u.active?'Ativo':'Inativo')}<button class="btn btn-secondary btn-small" data-action="user-edit" data-id="${u.id}">Editar</button><button class="btn btn-ghost btn-small" data-action="user-toggle" data-id="${u.id}">${u.active?'Desativar':'Ativar'}</button></div></div>`).join('')}</div>`;
    if(tab==='audit')return `<div class="panel-head"><div><span class="panel-kicker">RASTREABILIDADE</span><h2>Histórico de atividades</h2></div></div><div class="timeline">${db.audit.slice(0,80).map(a=>`<div class="timeline-item"><strong>${esc(a.user)} · ${esc(a.action)}</strong><p>${esc(a.detail)}</p><small>${esc(a.area)} · ${dateTimeBR(a.at)}</small></div>`).join('')}</div>`;
    if(tab==='cloud')return `<div class="panel-head"><div><span class="panel-kicker">SISTEMA ONLINE</span><h2>Sincronização entre computadores</h2></div><button class="btn btn-primary btn-small" data-action="cloud-sync-settings">${icon('i-settings')}Configurar</button></div><div class="card-grid"><article class="entity-card"><span class="badge info">NUVEM</span><h3 style="margin-top:12px">Banco central de dados</h3><p>A versão instalada e a versão web usam a mesma base central pela internet. Alterações feitas em um computador ou navegador são mescladas e distribuídas aos demais.</p><button class="btn btn-secondary" data-action="cloud-sync-test">Testar conexão</button></article><article class="entity-card"><span class="badge success">CRIPTOGRAFADO</span><h3 style="margin-top:12px">Publicar este computador</h3><p>Use somente no primeiro computador ou quando desejar enviar a base local atual para o servidor online.</p><button class="btn btn-secondary" data-action="cloud-sync-publish">Enviar dados locais</button></article><article class="entity-card"><span class="badge warning">SINCRONIZAR</span><h3 style="margin-top:12px">Baixar dados da nuvem</h3><p>Substitui a cópia local pela versão central mais recente. O sistema recarrega automaticamente após a sincronização.</p><button class="btn btn-secondary" data-action="cloud-sync-pull">Atualizar agora</button></article></div><div class="access-rule-box" style="margin-top:16px"><strong>Como funciona</strong><p>Os dados são criptografados no computador antes do envio. O servidor armazena somente o conteúdo criptografado e controla a revisão. Em alterações simultâneas, o sistema faz uma mesclagem de três vias para preservar registros diferentes sempre que possível.</p></div>`;
    if(tab==='backup')return `<div class="panel-head"><div><span class="panel-kicker">PROTEÇÃO DE DADOS</span><h2>Backup e restauração</h2></div></div><div class="card-grid"><article class="entity-card"><h3>Exportar backup</h3><p>Baixe uma cópia completa dos dados em JSON.</p><button class="btn btn-secondary" data-action="backup-export">Baixar backup</button></article><article class="entity-card"><h3>Restaurar backup</h3><p>Importe um arquivo criado pelo sistema.</p><label class="btn btn-secondary">Selecionar arquivo<input id="backupImportInput" type="file" accept="application/json" hidden></label></article><article class="entity-card"><h3>Restaurar demonstração</h3><p>Apaga as alterações locais e recupera os dados iniciais.</p><button class="btn btn-danger" data-action="demo-reset">Restaurar dados</button></article></div>`;
    const c=activeChurch();return `<div class="panel-head"><div><span class="panel-kicker">IDENTIDADE INSTITUCIONAL</span><h2>Dados da igreja</h2></div></div><form data-form="church" class="form-grid">${imageUploadField('image','Imagem da igreja',c.image||'','wide','Use uma foto da fachada, templo ou identidade visual da unidade.')}<label class="field span-2"><span>Nome da igreja</span><input name="name" value="${esc(c.name)}" required></label><label class="field span-2"><span>Razão social</span><input name="legalName" value="${esc(c.legalName)}"></label><label class="field"><span>CNPJ</span><input name="cnpj" value="${esc(c.cnpj)}"></label><label class="field"><span>Pastor responsável</span><input name="pastor" value="${esc(c.pastor)}"></label><label class="field"><span>Telefone</span><input name="phone" value="${esc(c.phone)}"></label><label class="field"><span>E-mail</span><input name="email" type="email" value="${esc(c.email)}"></label><label class="field"><span>CEP</span><input name="cep" value="${esc(c.cep||'')}"></label><label class="field span-2"><span>Endereço</span><input name="address" value="${esc(c.address)}"></label><label class="field"><span>Cidade</span><input name="city" value="${esc(c.city)}"></label><label class="field"><span>Estado</span><input name="state" value="${esc(c.state)}" maxlength="2"></label><div class="form-actions"><button class="btn btn-primary">Salvar alterações</button></div></form>`;
  }

  function confirmedTransactions(){return db.transactions.filter(t=>t.status==='confirmado')}
  function adjustmentImpact(accountId){return sum(db.cashAdjustments.filter(a=>a.type==='reforco'&&a.sessionId&&byId('cashSessions',a.sessionId)?.accountId===accountId),a=>a.amount)-sum(db.cashAdjustments.filter(a=>a.type==='sangria'&&a.sessionId&&byId('cashSessions',a.sessionId)?.accountId===accountId),a=>a.amount)+sum(db.cashAdjustments.filter(a=>a.type==='sangria'&&a.counterpartAccountId===accountId),a=>a.amount)-sum(db.cashAdjustments.filter(a=>a.type==='reforco'&&a.counterpartAccountId===accountId),a=>a.amount)}
  function accountBalance(id){const a=byId('accounts',id);return Number(a?.initialBalance||0)+sum(confirmedTransactions().filter(t=>t.accountId===id&&t.type==='entrada'),t=>t.amount)-sum(confirmedTransactions().filter(t=>t.accountId===id&&t.type==='saida'),t=>t.amount)+adjustmentImpact(id)}
  function totalBalance(){return sum(db.accounts,a=>accountBalance(a.id))}
  const CASH_DENOMS=[['20000','R$ 200,00',200],['10000','R$ 100,00',100],['5000','R$ 50,00',50],['2000','R$ 20,00',20],['1000','R$ 10,00',10],['500','R$ 5,00',5],['200','R$ 2,00',2],['100','R$ 1,00',1],['050','R$ 0,50',.5],['025','R$ 0,25',.25],['010','R$ 0,10',.1],['005','R$ 0,05',.05]];
  function cashAccounts(){return db.accounts.filter(a=>a.active&&normalize(a.type)==='caixa')}
  function openCashSessions(){return db.cashSessions.filter(s=>s.status==='Aberto').sort((a,b)=>b.openedAt.localeCompare(a.openedAt))}
  function cashSessionTransactions(id){return confirmedTransactions().filter(t=>t.cashSessionId===id&&!t.cashClosureAdjustment)}
  function cashSessionTotals(session){
    const tx=cashSessionTransactions(session.id),adj=db.cashAdjustments.filter(a=>a.sessionId===session.id);
    const income=sum(tx.filter(t=>t.type==='entrada'),t=>t.amount),expense=sum(tx.filter(t=>t.type==='saida'),t=>t.amount);
    const cashIncome=sum(tx.filter(t=>t.type==='entrada'&&normalize(t.method)==='dinheiro'),t=>t.amount),cashExpense=sum(tx.filter(t=>t.type==='saida'&&normalize(t.method)==='dinheiro'),t=>t.amount);
    const reinforcement=sum(adj.filter(a=>a.type==='reforco'),a=>a.amount),withdrawal=sum(adj.filter(a=>a.type==='sangria'),a=>a.amount);
    return {tx,adj,income,expense,cashIncome,cashExpense,reinforcement,withdrawal,expected:Number(session.openingBalance||0)+cashIncome-cashExpense+reinforcement-withdrawal};
  }
  function denominationFields(prefix,counts={},total=0){return `<div class="field span-2 cash-count-block"><div class="cash-count-head"><div><span class="panel-kicker">CONTAGEM FÍSICA</span><strong>Cédulas e moedas</strong></div><label><span>Total contado</span><input name="${prefix}Balance" data-currency data-cash-count-total="${prefix}Balance" value="${Number(total||0).toFixed(2)}" readonly></label></div><div class="cash-count-grid">${CASH_DENOMS.map(([key,label,value])=>`<label class="denomination-row"><span>${label}</span><input name="${prefix}_${key}" type="number" min="0" step="1" value="${Number(counts[key]||0)}" data-denomination data-denomination-value="${value}" data-denomination-target="${prefix}Balance"><small class="denomination-subtotal">${money(Number(counts[key]||0)*value)}</small></label>`).join('')}</div></div>`}
  function updateCashCount(form){if(!form)return;const groups={};form.querySelectorAll('[data-denomination]').forEach(input=>{const target=input.dataset.denominationTarget;(groups[target]??=0);groups[target]+=Number(input.value||0)*Number(input.dataset.denominationValue||0);input.closest('.denomination-row')?.querySelector('.denomination-subtotal')?.replaceChildren(document.createTextNode(money(Number(input.value||0)*Number(input.dataset.denominationValue||0))));});Object.entries(groups).forEach(([target,total])=>{const out=form.querySelector(`[data-cash-count-total="${target}"]`);if(out){if(window.CurrencyBRL?.setValue)window.CurrencyBRL.setValue(out,total);else out.value=total.toFixed(2);}});const expected=parseMoney(form.querySelector('[name="expectedBalance"]')?.value||0),counted=parseMoney(form.querySelector('[name="countedBalance"]')?.value||0),difference=form.querySelector('[data-cash-difference]');if(difference){const diff=counted-expected;difference.textContent=money(diff);difference.className=`cash-difference ${Math.abs(diff)<.01?'ok':diff>0?'positive':'negative'}`;}}
  function extractDenominations(obj,prefix){const counts={};CASH_DENOMS.forEach(([key])=>{counts[key]=Number(obj[`${prefix}_${key}`]||0);delete obj[`${prefix}_${key}`];});return counts}
  function treasuryCreditSettings(){
    const settings=db.treasurySettings||(db.treasurySettings={});
    const maxInstallments=Math.max(1,Math.min(24,Math.round(Number(settings.creditMaxInstallments||6))));
    const interest=Math.max(0,Math.min(100,Number(settings.creditInterestPerExtraInstallment||0)));
    return{maxInstallments,interest};
  }
  async function openCloudSyncSettings(){
    if(!window.santuarioDesktop?.cloudSyncStatus){showToast('Sincronização indisponível','O módulo de sincronização não foi carregado.','error');return;}
    const status=await window.santuarioDesktop.cloudSyncStatus();
    openModal({eyebrow:'SISTEMA ONLINE',title:'Sincronização entre computadores',subtitle:'Conecte este computador ao mesmo servidor e espaço de trabalho dos demais computadores.',wide:true,body:`<form data-form="cloud-sync-settings" class="form-grid"><label class="field span-2"><span>Ativar sincronização online</span><select name="enabled"><option value="true" ${status.enabled?'selected':''}>Ativada</option><option value="false" ${!status.enabled?'selected':''}>Desativada</option></select></label>${textField('serverUrl','Endereço do servidor',status.serverUrl||'','url','required placeholder="https://seu-servidor.exemplo.com"')}${textField('workspaceId','Código do espaço de trabalho',status.workspaceId||'','text','required placeholder="santuario-principal"')}${textField('accessToken',status.hasAccessToken?'Novo token de acesso (vazio mantém o atual)':'Token de acesso','','password',status.hasAccessToken?'autocomplete="new-password"':'required autocomplete="new-password"')}${textField('encryptionKey',status.hasEncryptionKey?'Nova chave de criptografia (vazio mantém a atual)':'Chave de criptografia','','password',status.hasEncryptionKey?'autocomplete="new-password" minlength="12"':'required autocomplete="new-password" minlength="12"')}<div class="field span-2 access-rule-box"><strong>Use exatamente os mesmos dados em todos os computadores</strong><p>Servidor, código do espaço, token e chave de criptografia identificam a mesma base online. A chave de criptografia não é enviada em texto aberto para armazenamento no servidor.</p></div>${modalActions()}</form>`});
  }
  async function cloudSyncTest(){const r=await window.santuarioDesktop?.testCloudSync?.();showToast(r?.ok?'Servidor online':'Falha na conexão',r?.ok?'Conexão estabelecida com sucesso.':(r?.error||'Revise a configuração.'),r?.ok?'success':'error');}
  async function cloudSyncPublish(){if(!confirm('Enviar a base atual deste computador para a nuvem? Em caso de dados já existentes, o sistema fará a mesclagem.'))return;showToast('Sincronizando','Enviando dados para o servidor...');const r=await window.santuarioDesktop?.publishLocalToCloud?.();showToast(r?.ok?'Dados sincronizados':'Falha na sincronização',r?.ok?`Revisão online ${r.revision||'atualizada'}.`:(r?.error||'Não foi possível enviar.'),r?.ok?'success':'error');}
  async function cloudSyncPull(){if(!confirm('Baixar a versão online mais recente? A página será recarregada.'))return;const r=await window.santuarioDesktop?.pullCloudNow?.();if(!r?.ok)showToast('Falha na sincronização',r?.error||'Não foi possível baixar os dados.','error');}

  function openCreditInstallmentSettings(){
    if(!canWriteFinance()){showToast('Acesso restrito','Seu perfil não pode alterar parâmetros do Caixa.','error');return;}
    const cfg=treasuryCreditSettings();
    openModal({eyebrow:'TESOURARIA E CAIXA',title:'Parcelamento no cartão de crédito',subtitle:'Defina quantas parcelas o Caixa oferecerá e o percentual de juros aplicado a cada parcela adicional.',body:`<form data-form="credit-installment-settings" class="form-grid">${textField('creditMaxInstallments','Quantidade máxima de parcelas',cfg.maxInstallments,'number','required min="1" max="24" step="1"')}${textField('creditInterestPerExtraInstallment','Juros por parcela adicional (%)',cfg.interest,'number','required min="0" max="100" step="0.01"')}<div class="field span-2 access-rule-box"><strong>Como o cálculo funciona</strong><p><b>1x é sempre sem juros.</b> A partir de 2x, cada parcela adicional acrescenta o percentual configurado sobre o valor original. Ex.: juros de 2% → 2x = 2% de acréscimo; 3x = 4%; 4x = 6%.</p></div>${modalActions()}</form>`});
  }
  function treasuryIntegrationSettings(){
    const settings=db.treasurySettings||(db.treasurySettings={});
    const rawCard=String(settings.paymentProvider||'MANUAL').toUpperCase();
    const rawPix=String(settings.pixProvider||'MANUAL_STATIC').toUpperCase();
    const paymentProvider=['MANUAL','INFINITEPAY','GENERIC_HTTP'].includes(rawCard)?rawCard:(rawCard&&rawCard!=='MANUAL'? 'GENERIC_HTTP':'MANUAL');
    const pixProvider=['MANUAL_STATIC','INFINITEPAY','GENERIC_HTTP'].includes(rawPix)?rawPix:(rawPix&&rawPix!=='MANUAL_STATIC'?'GENERIC_HTTP':'MANUAL_STATIC');
    return{paymentProvider,paymentBridgeUrl:String(settings.paymentBridgeUrl||''),pixProvider,pixStatusEndpoint:String(settings.pixStatusEndpoint||''),infinitePayHandle:String(settings.infinitePayHandle||''),infinitePayDocument:String(settings.infinitePayDocument||''),infinitePayCardChannel:String(settings.infinitePayCardChannel||'TAP').toUpperCase()};
  }
  function openPaymentIntegrationSettings(){
    if(!canWriteFinance()){showToast('Acesso restrito','Seu perfil não pode alterar integrações do Caixa.','error');return;}
    const cfg=treasuryIntegrationSettings();
    openModal({eyebrow:'TESOURARIA E CAIXA',title:'Integrações de pagamento',subtitle:'Ative provedores reais sem alterar o fluxo do Caixa. InfinitePay usa as integrações oficiais Checkout e InfiniteTap.',wide:true,body:`<form data-form="payment-integration-settings" class="form-grid">${selectField('paymentProvider','Cartões / maquininha',[['MANUAL','Manual'],['INFINITEPAY','InfinitePay'],['GENERIC_HTTP','Outro provedor · TEF/API HTTP']],cfg.paymentProvider)}${selectField('pixProvider','PIX',[['MANUAL_STATIC','PIX manual / QR estático'],['INFINITEPAY','InfinitePay Checkout'],['GENERIC_HTTP','Outro banco / PSP · API HTTP']],cfg.pixProvider)}${textField('infinitePayHandle','InfiniteTag',cfg.infinitePayHandle,'text','placeholder="Ex.: adoradoresdecristo"')}${textField('infinitePayDocument','CPF / CNPJ vinculado à InfinitePay',cfg.infinitePayDocument,'text','placeholder="Somente números ou formatado"')}${selectField('infinitePayCardChannel','Canal InfinitePay para cartão',[['TAP','InfiniteTap no celular (débito e crédito)'],['CHECKOUT','Checkout Integrado (crédito online)']],cfg.infinitePayCardChannel)}${textField('paymentBridgeUrl','Conector de outro provedor / TEF',cfg.paymentBridgeUrl,'url','placeholder="http://127.0.0.1:porta/pagamento"')}${textField('pixStatusEndpoint','Endpoint PIX de outro provedor',cfg.pixStatusEndpoint,'url','placeholder="https://... ou http://127.0.0.1:porta"')}<div class="field span-2 access-rule-box"><strong>InfinitePay já possui adaptador nativo nesta versão</strong><p>Para PIX, o sistema usa o Checkout Integrado e confere a transação antes de concluir a venda. Para cartão, o InfiniteTap envia valor, débito/crédito e parcelas ao aplicativo InfinitePay por deeplink. Como o Caixa roda no Windows e o InfiniteTap roda no celular, o retorno usa uma ponte na rede local: computador e celular devem estar no mesmo Wi‑Fi.</p></div><div class="field span-2 access-rule-box"><strong>Outros bancos e adquirentes</strong><p>O Caixa usa um hub de provedores. A opção TEF/API HTTP envia um payload padronizado ao conector escolhido. Assim Stone, Cielo, Rede, Getnet, PagBank e outros podem ser adicionados por adaptador sem redesenhar a tela de venda.</p></div>${modalActions()}</form>`});
  }

  function treasuryNotificationSettings(){
    const settings=db.treasurySettings||(db.treasurySettings={});
    settings.notifications={enabled:false,onOpen:true,onClose:true,onShortage:true,recipients:[],...(settings.notifications||{})};
    if(!Array.isArray(settings.notifications.recipients))settings.notifications.recipients=[];
    return settings.notifications;
  }
  function treasuryNotificationPhone(user){const linked=(db.members||[]).find(member=>normalize(member.name)===normalize(user.name));return String(user.phone||linked?.phone||'').trim();}
  function treasuryNotificationRecipientRule(userId){return treasuryNotificationSettings().recipients.find(item=>item.userId===userId)||{userId,email:false,sms:false};}
  function sendTreasuryAlertFromMain(eventType,payload={}){
    const cfg=treasuryNotificationSettings(),type=String(eventType||'').toUpperCase();
    if(!cfg.enabled||!window.santuarioDesktop?.sendTreasuryNotification)return;
    if(type==='OPEN'&&cfg.onOpen===false)return;
    if((type==='CLOSE'||type==='FORCED_CLOSE')&&cfg.onClose===false)return;
    if(type==='SHORTAGE'&&cfg.onShortage===false)return;
    const recipients=(cfg.recipients||[]).map(rule=>{const user=byId('users',rule.userId);if(!user||user.active===false)return null;return{userId:user.id,name:user.name,email:String(user.email||'').trim(),phone:treasuryNotificationPhone(user),emailEnabled:Boolean(rule.email),smsEnabled:Boolean(rule.sms)}}).filter(Boolean);
    if(!recipients.length)return;
    window.santuarioDesktop.sendTreasuryNotification({eventType:type,recipients,payload:{...payload,churchName:activeChurch()?.name||db.church?.name||'Santuário Gestão'}}).then(result=>{if(result?.results?.some(item=>!item.ok))console.warn('Alguns alertas da Tesouraria falharam',result.results.filter(item=>!item.ok));}).catch(()=>{});
  }
  function treasuryOpenOperationRows(){
    const internal=(db.treasuryOperations||[]).filter(item=>item.status==='Aberto').map(item=>({id:item.id,type:'Interna',number:item.number||'',title:item.title||'Tesouraria Interna',operator:item.openedBy||'',openedAt:item.openedAt||'',detail:item.serviceType||item.congregation||''}));
    const external=(db.externalCashSessions||[]).filter(item=>item.status==='Aberto').map(item=>({id:item.id,type:'Externa',number:item.number||'',title:item.eventName||item.pointOfSale||'Tesouraria Externa',operator:item.operator||'',openedAt:item.openedAt||'',detail:[item.saleType,item.pointOfSale].filter(Boolean).join(' · ')}));
    const physical=(db.cashSessions||[]).filter(item=>item.status==='Aberto').map(item=>({id:item.id,type:'Caixa',number:item.id||'',title:item.label||'Caixa da Tesouraria',operator:item.openedBy||'',openedAt:item.openedAt||'',detail:item.event||item.shift||''}));
    return [...internal,...external,...physical].sort((a,b)=>String(b.openedAt).localeCompare(String(a.openedAt)));
  }
  function treasuryLiveOperationsMarkup(){
    const rows=treasuryOpenOperationRows();
    if(!rows.length)return `<article class="treasury-live-monitor empty"><div class="treasury-live-monitor-head"><div><span class="panel-kicker">OPERAÇÕES EM TEMPO REAL</span><h2>Nenhuma tesouraria aberta</h2><p>Quando uma Tesouraria Interna ou Externa for aberta, ela permanecerá indicada aqui até o fechamento efetivo.</p></div><span class="badge success">Tudo fechado</span></div></article>`;
    return `<section class="treasury-live-monitor"><div class="treasury-live-monitor-head"><div><span class="panel-kicker">OPERAÇÕES EM TEMPO REAL</span><h2>${rows.length} operação${rows.length===1?'':'ões'} aberta${rows.length===1?'':'s'}</h2><p>Estas operações continuam abertas mesmo que você navegue para outro departamento ou minimize a janela do Caixa.</p></div><button class="btn btn-primary btn-small" data-action="open-treasury-login">${icon('i-cash')}ABRIR / TRAZER CAIXA</button></div><div class="treasury-live-grid">${rows.map(row=>`<article><span class="cash-live-status"><i></i> ${esc(row.type.toUpperCase())} ABERTA</span><strong>${esc(row.title)}</strong><small>${esc(row.number)}${row.detail?` · ${esc(row.detail)}`:''}</small><div><span>Aberta em ${dateTimeBR(row.openedAt)}</span><b>${esc(row.operator||'Operador não identificado')}</b></div></article>`).join('')}</div></section>`;
  }
  async function openTreasuryNotificationSettings(){
    if(!canWriteFinance()){showToast('Acesso restrito','Seu perfil não pode alterar alertas da Tesouraria.','error');return;}
    const cfg=treasuryNotificationSettings();
    const status=await window.santuarioDesktop?.treasuryNotificationStatus?.().catch(()=>null)||{};
    const users=(db.users||[]).filter(user=>user.active!==false);
    const recipientRows=users.map(user=>{const rule=treasuryNotificationRecipientRule(user.id),phone=treasuryNotificationPhone(user);return `<article class="treasury-notify-recipient"><div><span class="avatar">${initials(user.name)}</span><div><strong>${esc(user.name)}</strong><small>${esc(user.email||'Sem e-mail')} · ${esc(phone||'Sem telefone')}</small></div></div><label><input type="checkbox" name="notify_email_${user.id}" ${rule.email?'checked':''}> E-mail</label><label><input type="checkbox" name="notify_sms_${user.id}" ${rule.sms?'checked':''}> SMS</label></article>`}).join('');
    const smtp=status.smtp||{},twilio=status.twilio||{};
    openModal({eyebrow:'TESOURARIA E CAIXA',title:'Alertas de Tesouraria',subtitle:'Escolha quem será avisado quando uma operação abrir, fechar ou apresentar falta. As credenciais dos provedores ficam criptografadas no Windows.',wide:true,body:`<form data-form="treasury-notification-settings" class="form-grid treasury-notify-form"><div class="field span-2 notification-event-grid"><label><input type="checkbox" name="notifyEnabled" ${cfg.enabled?'checked':''}><span><strong>ATIVAR ALERTAS</strong><small>Envia mensagens automaticamente nos eventos selecionados.</small></span></label><label><input type="checkbox" name="notifyOpen" ${cfg.onOpen!==false?'checked':''}><span><strong>Abertura</strong><small>Tesouraria aberta.</small></span></label><label><input type="checkbox" name="notifyClose" ${cfg.onClose!==false?'checked':''}><span><strong>Fechamento</strong><small>Normal ou forçado.</small></span></label><label><input type="checkbox" name="notifyShortage" ${cfg.onShortage!==false?'checked':''}><span><strong>Falta</strong><small>Diferença negativa apurada.</small></span></label></div><div class="field span-2"><span>Destinatários</span><div class="treasury-notify-recipient-list">${recipientRows||'<div class="access-rule-box"><p>Nenhum usuário ativo foi encontrado.</p></div>'}</div></div><div class="field span-2 integration-provider-status"><div><span class="panel-kicker">E-MAIL · SMTP</span><strong>${status.emailConfigured?'Configurado':'Não configurado'}</strong><small>${status.emailConfigured?'O servidor SMTP está pronto para envio.':'Preencha servidor, usuário e senha para ativar E-mail.'}</small></div><span class="badge ${status.emailConfigured?'success':'warning'}">${status.emailConfigured?'ATIVO':'PENDENTE'}</span></div>${textField('smtpHost','Servidor SMTP',smtp.host||'','text','placeholder="smtp.gmail.com"')}${textField('smtpPort','Porta SMTP',smtp.port||587,'number','min="1" max="65535"')}${selectField('smtpSecure','Conexão SMTP',[['false','STARTTLS / porta 587'],['true','SSL/TLS direto / porta 465']],String(Boolean(smtp.secure)))}${textField('smtpUser','Usuário SMTP',smtp.user||'','text','autocomplete="off"')}${textField('smtpPassword',status.emailConfigured?'Nova senha SMTP (vazio mantém a atual)':'Senha SMTP','', 'password','autocomplete="new-password"')}${textField('smtpFromEmail','E-mail remetente',smtp.fromEmail||'','email','placeholder="tesouraria@dominio.com"')}${textField('smtpFromName','Nome do remetente',smtp.fromName||'Santuário Gestão') }<div class="field span-2 integration-provider-status"><div><span class="panel-kicker">SMS · TWILIO</span><strong>${status.smsConfigured?'Configurado':'Não configurado'}</strong><small>O telefone dos destinatários deve estar cadastrado no usuário ou em um membro com o mesmo nome.</small></div><span class="badge ${status.smsConfigured?'success':'warning'}">${status.smsConfigured?'ATIVO':'PENDENTE'}</span></div>${textField('twilioAccountSid','Twilio Account SID',twilio.accountSid||'','text','autocomplete="off"')}${textField('twilioAuthToken',status.smsConfigured?'Novo Auth Token (vazio mantém o atual)':'Twilio Auth Token','', 'password','autocomplete="new-password"')}${textField('twilioFromNumber','Número remetente Twilio',twilio.fromNumber||'','text','placeholder="+15551234567"')}<div class="field span-2 access-rule-box"><strong>Envio real</strong><p>O E-mail usa SMTP e o SMS usa a API da Twilio. Se um canal não estiver configurado, somente aquele canal será ignorado; a operação da Tesouraria nunca será bloqueada por falha de mensagem.</p></div>${modalActions()}</form>`});
  }
  function treasuryNotificationStrip(){
    const cfg=treasuryNotificationSettings(),selected=(cfg.recipients||[]).filter(r=>r.email||r.sms).length;
    return `<article class="credit-config-strip treasury-notification-strip"><div class="credit-config-icon">${icon('i-bell')}</div><div><span class="panel-kicker">ALERTAS DE TESOURARIA</span><strong>${cfg.enabled?'Notificações automáticas ativas':'Notificações automáticas desativadas'}</strong><small>${selected} destinatário${selected===1?'':'s'} · abertura ${cfg.onOpen!==false?'✓':'—'} · fechamento ${cfg.onClose!==false?'✓':'—'} · falta ${cfg.onShortage!==false?'✓':'—'}</small></div>${canWriteFinance()?`<button class="btn btn-secondary btn-small" data-action="treasury-notification-settings">${icon('i-settings')}Configurar</button>`:''}</article>`;
  }

  function openTreasuryForceClose(){
    const external=(db.externalCashSessions||[]).filter(item=>item.status==='Aberto').map(item=>({value:`external:${item.id}`,label:`Externa · ${item.number} · ${item.eventName||item.pointOfSale||'Caixa'}`}));
    const cashRows=(db.cashSessions||[]).filter(item=>item.status==='Aberto').map(item=>({value:`cash:${item.id}`,label:`Caixa da Tesouraria · ${item.label||item.id}`}));
    const internal=(db.treasuryOperations||[]).filter(item=>item.status==='Aberto').map(item=>({value:`internal:${item.id}`,label:`Tesouraria Interna · ${item.title||item.number||item.id}`}));
    const rows=[...external,...cashRows,...internal];
    if(!rows.length){showToast('Nenhuma operação aberta','Não existe operação para fechamento forçado.');return;}
    openModal({eyebrow:'SEGURANÇA OPERACIONAL',title:'FECHAR FORÇADO',subtitle:'Use somente quando uma operação ficou aberta indevidamente. Apenas códigos JP133 ou FM130 podem autorizar.',body:`<form data-form="treasury-force-close" class="form-grid">${selectField('target','Operação a encerrar',rows.map(row=>[row.value,row.label]),rows[0].value)}${textField('authIdentity','Login / código autorizado','','text','required autocomplete="off" placeholder="JP133 ou FM130"')}${textField('authPassword','Senha financeira','','password','required autocomplete="off"')}<label class="field span-2"><span>Motivo do fechamento forçado</span><textarea name="reason" required placeholder="Explique por que a operação não pôde ser fechada normalmente"></textarea></label><div class="field span-2 access-rule-box"><strong>Auditoria obrigatória</strong><p>O encerramento será marcado como FORÇADO e registrará usuário, data, hora e motivo. Ele não simula contagem de dinheiro nem cria uma conferência inexistente.</p></div>${modalActions()}</form>`});
  }
  function renderCashRegister(){
    const opens=openCashSessions(),closed=[...db.cashSessions].filter(s=>s.status==='Fechado').sort((a,b)=>(b.closedAt||'').localeCompare(a.closedAt||''));
    const actions=canWriteFinance()?`${actionButton('open-treasury-login','ABRIR CAIXA','i-cash')}<button class="btn btn-danger" data-action="treasury-force-close">${icon('i-close')}FECHAR FORÇADO</button>`:'';
    const live=opens.length?opens.map(session=>{const t=cashSessionTotals(session),account=byId('accounts',session.accountId);return `<article class="cash-session-live"><div class="cash-live-head"><div><span class="cash-live-status"><i></i> CAIXA ABERTO</span><h2>${esc(session.label)}</h2><p>${esc(session.event||'Operação de tesouraria')} · ${esc(session.shift||'Turno não informado')}</p></div><div class="cash-live-actions"><button class="btn btn-secondary btn-small" data-action="cash-new-income" data-id="${session.id}">${icon('i-arrow-up')}Entrada</button><button class="btn btn-secondary btn-small" data-action="cash-new-expense" data-id="${session.id}">${icon('i-arrow-down')}Saída</button><button class="btn btn-secondary btn-small" data-action="cash-reinforcement" data-id="${session.id}">Reforço</button><button class="btn btn-secondary btn-small" data-action="cash-withdrawal" data-id="${session.id}">Sangria</button><button class="btn btn-danger btn-small" data-action="cash-close" data-id="${session.id}">${icon('i-check')}Fechar caixa</button></div></div><div class="cash-summary-grid"><div><small>Conta física</small><strong>${esc(account?.name||'Caixa')}</strong></div><div><small>Aberto em</small><strong>${dateTimeBR(session.openedAt)}</strong></div><div><small>Operador</small><strong>${esc(session.openedBy)}</strong></div><div><small>Saldo inicial</small><strong>${money(session.openingBalance)}</strong></div><div><small>Entradas em dinheiro</small><strong class="amount-in">${money(t.cashIncome)}</strong></div><div><small>Saídas em dinheiro</small><strong class="amount-out">${money(t.cashExpense)}</strong></div><div><small>Reforços / sangrias</small><strong>${money(t.reinforcement)} / ${money(t.withdrawal)}</strong></div><div class="cash-expected"><small>Saldo físico esperado</small><strong>${money(t.expected)}</strong></div></div><div class="cash-session-body"><div><span class="panel-kicker">MOVIMENTAÇÕES DA SESSÃO</span>${t.tx.length?t.tx.slice(0,8).map(x=>`<div class="activity-item"><span class="activity-icon ${x.type==='entrada'?'in':'out'}">${icon(x.type==='entrada'?'i-arrow-up':'i-arrow-down')}</span><div class="activity-main"><strong>${esc(x.description)}</strong><small>${esc(x.method)} · ${esc(x.category)}</small></div><strong class="${x.type==='entrada'?'amount-in':'amount-out'}">${x.type==='entrada'?'+':'−'} ${money(x.amount)}</strong></div>`).join(''):emptyState('i-receipt','Sem movimentações','Registre entradas e saídas durante esta sessão.')}</div><div><span class="panel-kicker">RESUMO POR FORMA</span>${['Dinheiro','PIX','Cartão','Transferência','Misto'].map(method=>{const val=sum(t.tx.filter(x=>normalize(x.method)===normalize(method)&&x.type==='entrada'),x=>x.amount);return `<div class="settings-item"><div><strong>${method}</strong><small>Entradas vinculadas</small></div><strong>${money(val)}</strong></div>`}).join('')}</div></div></article>`}).join(''):`<article class="cash-closed-state">${icon('i-cash')}<div><span class="panel-kicker">TESOURARIA</span><h2>Nenhum caixa está aberto</h2><p>Abra uma sessão antes de iniciar a contagem e o recebimento presencial.</p></div>${canWriteFinance()?`<button class="btn btn-primary" data-action="open-treasury-login">${icon('i-cash')}ABRIR CAIXA</button>`:''}</article>`;
    return `<div class="page">${pageTitle('ABERTURA E FECHAMENTO','Caixa da tesouraria','Controle operacional por turno com contagem física, reforços, sangrias, divergências e termo de fechamento.',actions)}${treasuryLiveOperationsMarkup()}${live}<div class="metrics-grid">${metric('Caixas abertos',opens.length,'i-cash','Sessões em andamento')}${metric('Fechamentos no mês',closed.filter(s=>monthKey((s.closedAt||'').slice(0,10))===currentMonth()).length,'i-check','Sessões concluídas')}${metric('Diferenças no mês',money(sum(closed.filter(s=>monthKey((s.closedAt||'').slice(0,10))===currentMonth()),s=>Math.abs(s.difference||0))),'i-shield','Sobras e faltas apuradas','coral')}${metric('Caixas disponíveis',cashAccounts().length,'i-wallet','Contas físicas ativas','gold')}</div>${(()=>{const cfg=treasuryCreditSettings();return `<article class="credit-config-strip"><div class="credit-config-icon">${icon('i-wallet')}</div><div><span class="panel-kicker">CARTÃO DE CRÉDITO</span><strong>Parcelamento do Caixa</strong><small>Até ${cfg.maxInstallments}x · ${cfg.interest.toLocaleString('pt-BR',{maximumFractionDigits:2})}% de juros por parcela adicional</small></div>${canWriteFinance()?`<button class="btn btn-secondary btn-small" data-action="credit-installment-settings">${icon('i-settings')}Configurar</button>`:''}</article>`})()}${(()=>{const cfg=treasuryIntegrationSettings(),infinite=cfg.paymentProvider==='INFINITEPAY'||cfg.pixProvider==='INFINITEPAY',configured=infinite||cfg.paymentProvider==='GENERIC_HTTP'||cfg.pixProvider==='GENERIC_HTTP';const cardLabel=cfg.paymentProvider==='INFINITEPAY'?`InfinitePay ${cfg.infinitePayCardChannel==='CHECKOUT'?'Checkout':'InfiniteTap'}`:cfg.paymentProvider==='GENERIC_HTTP'?'TEF/API externo':'Cartão manual';const pixLabel=cfg.pixProvider==='INFINITEPAY'?'InfinitePay Checkout':cfg.pixProvider==='GENERIC_HTTP'?'API PIX externa':'PIX manual';return `<article class="credit-config-strip integration-config-strip"><div class="credit-config-icon">${icon('i-refresh')}</div><div><span class="panel-kicker">INTEGRAÇÕES DE PAGAMENTO</span><strong>${configured?'Hub de pagamentos configurado':'Modo manual ativo'}</strong><small>${esc(cardLabel)} · ${esc(pixLabel)}${infinite&&cfg.infinitePayHandle?` · $${esc(cfg.infinitePayHandle)}`:''}</small></div>${canWriteFinance()?`<button class="btn btn-secondary btn-small" data-action="payment-integration-settings">${icon('i-settings')}Configurar</button>`:''}</article>`})()}${treasuryNotificationStrip()}<div class="workspace"><div class="workspace-toolbar"><strong>Histórico de abertura e fechamento</strong></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Abertura</th><th>Identificação</th><th>Operador</th><th>Saldo inicial</th><th>Esperado</th><th>Contado</th><th>Diferença</th><th>Status</th><th>Ações</th></tr></thead><tbody>${[...opens,...closed].map(session=>`<tr><td>${dateTimeBR(session.openedAt)}</td><td><strong>${esc(session.label)}</strong><small>${esc(byId('accounts',session.accountId)?.name||'—')} · ${esc(session.shift||'')}</small></td><td>${esc(session.openedBy)}<small>${session.closedBy?`Fechado por ${esc(session.closedBy)}`:'Em operação'}</small></td><td>${money(session.openingBalance)}</td><td>${session.status==='Fechado'?money(session.expectedBalance):money(cashSessionTotals(session).expected)}</td><td>${session.status==='Fechado'?money(session.countedBalance):'—'}</td><td class="${Number(session.difference||0)===0?'amount-in':'amount-out'}">${session.status==='Fechado'?money(session.difference):'—'}</td><td>${badge(session.status)}</td><td><div class="table-actions">${session.status==='Fechado'?`<button data-action="cash-print" data-id="${session.id}" title="Imprimir termo">${icon('i-print')}</button>`:`<button data-action="cash-close" data-id="${session.id}" title="Fechar caixa">${icon('i-check')}</button>`}</div></td></tr>`).join('')}</tbody></table>${db.cashSessions.length?'':emptyState('i-cash','Sem histórico','A primeira abertura de caixa aparecerá aqui.')}</div></div></div>`;
  }
  function cashDashboardStrip(){
    const internalOpen=(db.treasuryOperations||[]).filter(o=>(o.type==='internal'||o.type==='cult')&&o.status==='Aberto');
    const externalOpen=(db.externalCashSessions||[]).filter(o=>o.status==='Aberto');
    const count=internalOpen.length+externalOpen.length;
    if(!count)return `<button class="cash-dashboard-strip closed" data-action="open-treasury-login"><span class="activity-icon in">${icon('i-cash')}</span><div><small>TESOURARIA E CAIXA</small><strong>Nenhuma operação aberta</strong><p>Abra uma Tesouraria Interna ou um caixa de vendas externo.</p></div><span class="cash-strip-link">ABRIR CAIXA ${icon('i-chevron')}</span></button>`;
    const labels=[...internalOpen.map(o=>`Interna: ${o.title}`),...externalOpen.map(o=>`Externa: ${o.eventName}`)];
    return `<button class="cash-dashboard-strip open" data-action="open-treasury-login"><span class="cash-live-status"><i></i> ${count} ABERTA${count>1?'S':''}</span><div><small>TESOURARIA E CAIXA</small><strong>${esc(labels[0]||'Operação em andamento')}</strong><p>${count>1?`${count} operações aguardando continuidade`:'Acesse o caixa autenticado para continuar'}</p></div><span class="cash-strip-link">Acessar ${icon('i-chevron')}</span></button>`;
  }
  function renderFinanceDashboard(){
    const monthly=confirmedTransactions().filter(t=>monthKey(t.date)===currentMonth()),income=sum(monthly.filter(t=>t.type==='entrada'),t=>t.amount),expense=sum(monthly.filter(t=>t.type==='saida'),t=>t.amount),pending=sum(db.bills.filter(b=>b.direction==='pagar'&&b.status!=='Paga'),b=>b.amount);
    return `<div class="page">${pageHero('finance',`${greeting()}, ${currentUser.name.split(' ')[0]}.`,'Acompanhe caixa, compromissos, orçamento e prestação de contas em uma visão executiva.',`${actionButton('open-treasury-login','ABRIR CAIXA','i-cash')}${actionButton('new-income','Nova entrada','i-arrow-up')}${actionButton('new-expense','Nova despesa','i-arrow-down',true)}`)}
      <section class="treasury-entry-banner">
        <div class="treasury-entry-icon">${icon('i-cash')}</div>
        <div class="treasury-entry-copy"><span class="panel-kicker">ACESSO OPERACIONAL PROTEGIDO</span><h2>Tesouraria Interna ou Tesouraria Externa</h2><p>Consulte os indicadores deste departamento normalmente. Para iniciar uma contagem de culto ou operar um ponto de venda, autentique-se no caixa.</p><div class="treasury-entry-tags"><span>Interna: cultos e contribuições</span><span>Externa: vendas e estoque</span><span>Fechamento auditado</span></div></div>
        <button class="btn btn-primary treasury-open-main" data-action="open-treasury-login">${icon('i-cash')}ABRIR CAIXA</button>
      </section>
      <div class="metrics-grid">${metric('Saldo consolidado',money(totalBalance()),'i-wallet','Todas as contas')}${metric('Entradas no mês',money(income),'i-arrow-up','Receitas confirmadas')}${metric('Saídas no mês',money(expense),'i-arrow-down','Despesas confirmadas','coral')}${metric('Contas a pagar',money(pending),'i-receipt','Compromissos em aberto','gold')}</div>${cashDashboardStrip()}
      <div class="dashboard-grid"><article class="panel span-8"><div class="panel-head"><div><span class="panel-kicker">FLUXO DE CAIXA</span><h2>Entradas e saídas — 6 meses</h2></div><div class="chart-legend"><span class="income">Entradas</span><span class="expense">Saídas</span></div></div>${cashFlowChart()}</article>
      <article class="panel span-4"><div class="panel-head"><div><span class="panel-kicker">CONTAS</span><h2>Saldos atuais</h2></div><button data-module="banking" class="text-button">Conciliar</button></div><div class="activity-list">${db.accounts.map(a=>`<div class="activity-item"><span class="activity-icon in">${icon('i-bank')}</span><div class="activity-main"><strong>${esc(a.name)}</strong><small>${esc(a.bank)} · ${esc(a.type)}</small></div><strong>${money(accountBalance(a.id))}</strong></div>`).join('')}</div></article>
      <article class="panel span-6"><div class="panel-head"><div><span class="panel-kicker">VENCIMENTOS</span><h2>Próximas contas</h2></div><button data-module="bills" class="text-button">Ver contas</button></div><div class="activity-list">${db.bills.filter(b=>b.status!=='Paga').sort((a,b)=>a.dueDate.localeCompare(b.dueDate)).slice(0,6).map(b=>`<div class="activity-item"><span class="activity-icon out">${icon('i-receipt')}</span><div class="activity-main"><strong>${esc(b.description)}</strong><small>Vence ${dateBR(b.dueDate)} · ${esc(b.category)}</small></div><strong>${money(b.amount)}</strong></div>`).join('')}</div></article>
      <article class="panel span-6"><div class="panel-head"><div><span class="panel-kicker">APROVAÇÕES</span><h2>Pendências de governança</h2></div><button data-module="approvals" class="text-button">Analisar</button></div><div class="activity-list">${db.approvals.filter(a=>a.status==='Pendente').map(a=>`<div class="activity-item"><span class="activity-icon out">${icon('i-shield')}</span><div class="activity-main"><strong>${esc(a.description)}</strong><small>${esc(a.requester)} · ${dateBR(a.requestedAt)}</small></div><strong>${money(a.amount)}</strong></div>`).join('')||emptyState('i-check','Tudo aprovado','Não existem solicitações pendentes.')}</div></article></div></div>`;
  }
  function cashFlowData(months=6){const result=[];for(let i=months-1;i>=0;i--){const d=new Date();d.setMonth(d.getMonth()-i);const key=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`,rows=confirmedTransactions().filter(t=>monthKey(t.date)===key);result.push({label:new Intl.DateTimeFormat('pt-BR',{month:'short'}).format(d).replace('.',''),income:sum(rows.filter(t=>t.type==='entrada'),t=>t.amount),expense:sum(rows.filter(t=>t.type==='saida'),t=>t.amount)})}return result}
  function cashFlowChart(){const data=cashFlowData(),max=Math.max(...data.flatMap(d=>[d.income,d.expense]),1);return `<div class="chart-bars">${data.map(d=>`<div class="chart-column"><div class="chart-pair"><i class="income" title="${money(d.income)}" style="height:${d.income/max*100}%"></i><i class="expense" title="${money(d.expense)}" style="height:${d.expense/max*100}%"></i></div><small>${d.label}</small></div>`).join('')}</div>`}


  function treasuryOperators(){
    return db.users.filter(user=>user.areas?.includes('finance')&&['admin','financeiro'].includes(user.role)&&Boolean(user.treasuryConfigured||user.treasuryLogin||user.treasuryCode));
  }
  function treasuryPermissionLabel(user){
    const p=user.treasuryPermissions||{};
    const labels=[];
    if(p.internal!==false)labels.push('Interna');
    if(p.external!==false)labels.push('Externa');
    if(p.open!==false)labels.push('Abrir');
    if(p.close!==false)labels.push('Fechar');
    return labels;
  }
  function renderTreasuryControl(){
    const operators=treasuryOperators();
    const activeSessions=(db.treasuryActiveSessions||[]).filter(item=>Number(item.expiresAt||0)>Date.now());
    const openInternal=(db.treasuryOperations||[]).filter(item=>item.status==='Aberto');
    const openExternal=(db.externalCashSessions||[]).filter(item=>item.status==='Aberto');
    const today=todayISO();
    const deniedToday=(db.treasuryAccessLog||[]).filter(item=>String(item.at||'').slice(0,10)===today&&['Negado','Bloqueado'].includes(item.result)).length;
    const canManage=currentUser?.role==='admin';
    const operatorCards=operators.map(user=>{
      const lastAccess=(db.treasuryAccessLog||[]).find(item=>(item.user===user.name||normalize(String(item.identity).replace(/[^a-z0-9]/gi,''))===normalize(String(user.treasuryCode||'').replace(/[^a-z0-9]/gi,'')))&&item.result==='Autorizado');
      const active=activeSessions.find(item=>item.userId===user.id);
      const permissions=treasuryPermissionLabel(user);
      return `<article class="treasury-control-operator ${user.treasuryAccess===false||!user.active?'blocked':''}">
        <div class="operator-card-head"><span class="avatar">${initials(user.name)}</span><div><h3>${esc(user.name)}</h3><p class="operator-code-line">Login <code>${esc(user.treasuryLogin||'Não definido')}</code> · Código <code>${esc(user.treasuryCode||'—')}</code></p></div>${badge(!user.active?'Usuário inativo':user.treasuryAccess===false?'Acesso bloqueado':active?'Sessão ativa':'Autorizado')}</div>
        <div class="operator-control-meta"><div><small>Perfil</small><strong>${esc(ROLE_LABELS[user.role]||user.role)}</strong></div><div><small>Último acesso</small><strong>${lastAccess?dateTimeBR(lastAccess.at):'Nunca registrado'}</strong></div></div>
        <div class="operator-permissions">${permissions.map(label=>`<span>${esc(label)}</span>`).join('')||'<span class="muted">Sem operações autorizadas</span>'}</div>
        ${active?`<div class="operator-session-live"><i></i><div><small>SESSÃO FINANCEIRA ATIVA</small><strong>Desde ${dateTimeBR(active.createdAt)}</strong><span>Última atividade: ${dateTimeBR(active.lastActivityAt)}</span></div></div>`:''}
        ${canManage?`<div class="operator-card-actions"><button class="btn btn-secondary btn-small" data-action="treasury-operator-edit" data-id="${user.id}">${icon('i-edit')}Configurar</button><button class="btn ${user.treasuryAccess===false?'btn-primary':'btn-ghost'} btn-small" data-action="treasury-operator-toggle" data-id="${user.id}">${user.treasuryAccess===false?'Liberar acesso':'Bloquear acesso'}</button></div>`:''}
      </article>`;
    }).join('');
    const activeRows=[...openInternal.map(item=>({type:'Interna',number:item.number,title:item.title,operator:item.openedBy,openedAt:item.openedAt||`${item.date}T${item.time}`,status:item.status})),...openExternal.map(item=>({type:'Externa',number:item.number,title:`${item.eventName} · ${item.pointOfSale}`,operator:item.operator,openedAt:item.openedAt,status:item.status}))];
    const logRows=(db.treasuryAccessLog||[]).slice(0,40);
    return `<div class="page">${pageTitle('SEGURANÇA OPERACIONAL','Controle da Tesouraria','Gerencie credenciais exclusivas da Tesouraria e do Caixa sem alterar o acesso ao sistema principal.',canManage?actionButton('treasury-operator-new','Adicionar acesso','i-users'):'')}
      <div class="metrics-grid">${metric('Operadores autorizados',operators.filter(user=>user.active&&user.treasuryAccess!==false).length,'i-users','Podem autenticar na Tesouraria')}${metric('Sessões ativas',activeSessions.length,'i-shield','Logins financeiros em andamento')}${metric('Operações abertas',activeRows.length,'i-cash','Tesourarias e caixas ativos','gold')}${metric('Acessos negados hoje',deniedToday,'i-alert','Tentativas bloqueadas','coral')}</div>
      <section class="workspace treasury-control-workspace"><div class="workspace-toolbar"><div><strong>Operadores da Tesouraria</strong><small>Cada operador entra usando o login exclusivo definido nesta tela.</small></div></div><div class="treasury-control-grid">${operatorCards||emptyState('i-users','Nenhum operador','Adicione acesso financeiro a um usuário já cadastrado em Configurações.')}</div></section>
      <div class="dashboard-grid treasury-control-sections">
        <section class="panel span-6"><div class="panel-head"><div><span class="panel-kicker">MONITORAMENTO</span><h2>Operações em andamento</h2></div><span class="badge warning">${activeRows.length} aberta${activeRows.length===1?'':'s'}</span></div>${activeRows.length?activeRows.map(row=>`<div class="control-live-operation"><span class="activity-icon ${row.type==='Interna'?'in':'out'}">${icon(row.type==='Interna'?'i-hand':'i-cash')}</span><div><strong>${esc(row.title)}</strong><small>${esc(row.number)} · ${esc(row.type)} · ${dateTimeBR(row.openedAt)}</small><p>Operador: ${esc(row.operator||'Não identificado')}</p></div>${badge(row.status)}</div>`).join(''):emptyState('i-check','Nenhuma operação aberta','Não há caixa ou tesouraria em andamento.')}</section>
        <section class="panel span-6"><div class="panel-head"><div><span class="panel-kicker">DOCUMENTOS</span><h2>Extratos de fechamento</h2></div><span class="badge info">${(db.treasuryClosureReports||[]).length}</span></div>${(db.treasuryClosureReports||[]).length?(db.treasuryClosureReports||[]).slice(0,8).map(report=>`<div class="settings-item"><div><strong>${esc(report.number)}</strong><small>${report.type==='external'?'Caixa externo':'Tesouraria interna'} · ${dateTimeBR(report.generatedAt)}</small></div><button class="btn btn-secondary btn-small" data-action="treasury-report-open" data-id="${report.id}">${icon('i-print')}Extrato</button></div>`).join(''):emptyState('i-doc','Sem extratos','Os documentos serão criados automaticamente ao fechar uma operação.')}</section>
      </div>
      <section class="workspace"><div class="workspace-toolbar"><div><strong>Registro de acessos</strong><small>Autenticações autorizadas, negadas e bloqueadas.</small></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Data e hora</th><th>Operador / usuário</th><th>Ação</th><th>Resultado</th><th>Detalhes</th></tr></thead><tbody>${logRows.map(log=>`<tr><td>${dateTimeBR(log.at)}</td><td><strong>${esc(log.user||log.identity||'Não identificado')}</strong><small>${esc(log.identity||'')}</small></td><td>${esc(log.action)}</td><td>${badge(log.result)}</td><td>${esc(log.detail||'—')}</td></tr>`).join('')}</tbody></table>${logRows.length?'':emptyState('i-shield','Sem registros','As tentativas de acesso aparecerão aqui.')}</div></section>
    </div>`;
  }

  function renderTransactions(){
    let rows=[...db.transactions].sort((a,b)=>b.date.localeCompare(a.date)); const q=normalize(state.query); if(q)rows=rows.filter(t=>normalize(`${t.description} ${t.category} ${t.document}`).includes(q));if(state.tab!=='all')rows=rows.filter(t=>t.type===state.tab);if(state.account!=='all')rows=rows.filter(t=>t.accountId===state.account);
    return `<div class="page">${pageTitle('LIVRO-CAIXA','Movimentações','Entradas e saídas com conta, centro de custo, documento, forma de pagamento e rastreabilidade.',canWriteFinance()?`${actionButton('new-expense','Registrar despesa','i-arrow-down',true)}${actionButton('new-income','Registrar entrada','i-arrow-up')}`:'')}
      <div class="workspace"><div class="workspace-toolbar"><div class="segmented"><button data-filter-tab="all" class="${state.tab==='all'?'active':''}">Todas</button><button data-filter-tab="entrada" class="${state.tab==='entrada'?'active':''}">Entradas</button><button data-filter-tab="saida" class="${state.tab==='saida'?'active':''}">Saídas</button></div><div class="toolbar-actions"><label class="search-field">${icon('i-search')}<input data-live-search value="${esc(state.query)}" placeholder="Buscar lançamento"></label><select data-filter-account class="compact-select"><option value="all">Todas as contas</option>${db.accounts.map(a=>`<option value="${a.id}" ${state.account===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select><button class="icon-button bordered" data-action="transactions-export">${icon('i-download')}</button></div></div>
      <div class="data-table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Descrição</th><th>Categoria / Centro</th><th>Conta</th><th>Documento</th><th>Valor</th><th>Ações</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${dateBR(t.date)}</td><td><strong>${esc(t.description)}</strong><small>${esc(t.method)} · ${esc(t.status)}${t.cashSessionId?` · Caixa: ${esc(byId('cashSessions',t.cashSessionId)?.label||'sessão')}`:''}</small></td><td>${esc(t.category)}<small>${esc(t.costCenter)}</small></td><td>${esc(byId('accounts',t.accountId)?.name||'—')}</td><td>${esc(t.document||'—')}</td><td class="${t.type==='entrada'?'amount-in':'amount-out'}">${t.type==='entrada'?'+':'−'} ${money(t.amount)}</td><td><div class="table-actions"><button data-action="transaction-receipt" data-id="${t.id}">${icon('i-receipt')}</button>${canWriteFinance()&&!(t.cashSessionId&&byId('cashSessions',t.cashSessionId)?.status==='Fechado')?`<button data-action="transaction-edit" data-id="${t.id}">${icon('i-edit')}</button><button data-action="transaction-delete" data-id="${t.id}">${icon('i-trash')}</button>`:t.cashSessionId?`<span class="badge info">Caixa fechado</span>`:''}</div></td></tr>`).join('')}</tbody></table></div></div></div>`;
  }

  function renderContributions(){
    let rows=db.contributions.filter(c=>!state.query||normalize(`${byId('members',c.memberId)?.name} ${c.type} ${c.receipt}`).includes(normalize(state.query)));
    const total=sum(rows,c=>c.amount),identified=rows.filter(c=>c.memberId).length;
    return `<div class="page">${pageTitle('DÍZIMOS, OFERTAS E DOAÇÕES','Contribuições','Histórico individual protegido, competência, recibo e identificação opcional.',canWriteFinance()?actionButton('new-contribution','Nova contribuição'): '')}
      <div class="metrics-grid">${metric('Total registrado',money(total),'i-hand','Contribuições da listagem')}${metric('Lançamentos',rows.length,'i-receipt','Registros encontrados')}${metric('Identificadas',identified,'i-users','Vinculadas a pessoas')}${metric('Anônimas',rows.length-identified,'i-shield','Sem identificação individual','gold')}</div>
      <div class="workspace">${searchToolbar('Buscar contribuinte, tipo ou recibo')}<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Competência</th><th>Contribuinte</th><th>Tipo</th><th>Recibo</th><th>Valor</th><th>Ações</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${esc(c.competence)}</td><td><strong>${esc(byId('members',c.memberId)?.name||'Anônimo / coletivo')}</strong></td><td>${esc(c.type)}</td><td>${esc(c.receipt)}</td><td class="amount-in">${money(c.amount)}</td><td><div class="table-actions"><button data-action="contribution-receipt" data-id="${c.id}">${icon('i-print')}</button>${canWriteFinance()?`<button data-action="contribution-edit" data-id="${c.id}">${icon('i-edit')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></div></div>`;
  }

  function renderBills(){
    let rows=[...db.bills].sort((a,b)=>a.dueDate.localeCompare(b.dueDate));if(state.tab!=='all')rows=rows.filter(b=>b.direction===state.tab);if(state.status!=='all')rows=rows.filter(b=>b.status===state.status);
    const openPay=sum(db.bills.filter(b=>b.direction==='pagar'&&b.status!=='Paga'),b=>b.amount),openReceive=sum(db.bills.filter(b=>b.direction==='receber'&&b.status!=='Recebida'),b=>b.amount);
    return `<div class="page">${pageTitle('COMPROMISSOS FINANCEIROS','Contas a pagar e receber','Vencimentos, recorrência, fornecedores, aprovação e liquidação vinculada ao caixa.',canWriteFinance()?actionButton('new-bill','Nova conta'): '')}
      <div class="metrics-grid">${metric('A pagar',money(openPay),'i-arrow-down','Compromissos em aberto','coral')}${metric('A receber',money(openReceive),'i-arrow-up','Direitos em aberto')}${metric('Vencem em 7 dias',db.bills.filter(b=>b.dueDate<=addDays(7)&&!['Paga','Recebida'].includes(b.status)).length,'i-calendar','Exigem atenção','gold')}${metric('Recorrentes',db.bills.filter(b=>b.recurrence!=='Única').length,'i-refresh','Contas periódicas','navy')}</div>
      <div class="workspace"><div class="workspace-toolbar"><div class="segmented"><button data-filter-tab="all" class="${state.tab==='all'?'active':''}">Todas</button><button data-filter-tab="pagar" class="${state.tab==='pagar'?'active':''}">A pagar</button><button data-filter-tab="receber" class="${state.tab==='receber'?'active':''}">A receber</button></div><select data-filter-status class="compact-select"><option value="all">Todos os status</option>${['Aberta','Em aprovação','Paga','Recebida'].map(s=>`<option ${state.status===s?'selected':''}>${s}</option>`).join('')}</select></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Vencimento</th><th>Descrição</th><th>Fornecedor</th><th>Recorrência</th><th>Status</th><th>Valor</th><th>Ações</th></tr></thead><tbody>${rows.map(b=>`<tr><td>${dateBR(b.dueDate)}</td><td><strong>${esc(b.description)}</strong><small>${esc(b.category)} · ${esc(b.document)}</small></td><td>${esc(byId('suppliers',b.supplierId)?.name||'—')}</td><td>${esc(b.recurrence)}</td><td>${badge(b.status)}</td><td class="${b.direction==='pagar'?'amount-out':'amount-in'}">${money(b.amount)}</td><td><div class="table-actions">${canWriteFinance()&&!['Paga','Recebida'].includes(b.status)?`<button data-action="bill-settle" data-id="${b.id}" title="Liquidar">${icon('i-check')}</button>`:''}${canWriteFinance()?`<button data-action="bill-edit" data-id="${b.id}">${icon('i-edit')}</button><button data-action="bill-delete" data-id="${b.id}">${icon('i-trash')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></div></div>`;
  }

  function renderBanking(){
    return `<div class="page">${pageTitle('CAIXA, BANCOS E CONCILIAÇÃO','Contas e conciliação','Saldos por conta, conferência de extratos e divergências de fechamento.',canWriteFinance()?`${actionButton('new-account','Nova conta','i-bank')}${actionButton('new-reconciliation','Nova conciliação','i-checklist',true)}`:'')}
      <div class="card-grid">${db.accounts.map(a=>`<article class="entity-card"><div class="entity-card-head"><span class="avatar">${icon('i-bank')}</span><div><h3>${esc(a.name)}</h3><p>${esc(a.bank)} · ${esc(a.type)}</p></div></div><strong style="font-size:1.6rem">${money(accountBalance(a.id))}</strong><p>Saldo atual calculado pelo livro-caixa.</p><div class="entity-meta"><div><small>Agência</small><strong>${esc(a.branch||'—')}</strong></div><div><small>Conta</small><strong>${esc(a.number||'—')}</strong></div></div>${canWriteFinance()?`<div class="page-title-actions" style="margin-top:12px"><button class="btn btn-secondary btn-small" data-action="account-edit" data-id="${a.id}">Editar</button></div>`:''}</article>`).join('')}</div>
      <div class="workspace" style="margin-top:16px"><div class="workspace-toolbar"><strong>Fechamentos e conciliações</strong></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Período</th><th>Conta</th><th>Extrato</th><th>Sistema</th><th>Diferença</th><th>Responsável</th><th>Status</th></tr></thead><tbody>${db.reconciliations.map(r=>`<tr><td>${esc(r.period)}</td><td>${esc(byId('accounts',r.accountId)?.name||'—')}</td><td>${money(r.statementBalance)}</td><td>${money(r.systemBalance)}</td><td class="${r.difference?'amount-out':'amount-in'}">${money(r.difference)}</td><td>${esc(r.owner)}</td><td>${badge(r.status)}</td></tr>`).join('')}</tbody></table></div></div></div>`;
  }

  function renderBudgets(){
    const planned=sum(db.budgets,b=>b.planned),realized=sum(db.budgets,b=>b.realized),pct=Math.round(realized/planned*100);
    return `<div class="page">${pageTitle('PLANEJAMENTO E CONTROLE','Orçamentos por centro de custo','Planejado, comprometido e realizado por ministério, projeto ou área administrativa.',canWriteFinance()?actionButton('new-budget','Novo orçamento'): '')}
      <div class="metrics-grid">${metric('Orçamento total',money(planned),'i-target','Planejado no exercício')}${metric('Realizado',money(realized),'i-wallet',`${pct}% do orçamento`)}${metric('Disponível',money(planned-realized),'i-arrow-up','Saldo orçamentário')}${metric('Centros de custo',db.budgets.length,'i-ministry','Orçamentos ativos','gold')}</div>
      <div class="card-grid">${db.budgets.map(b=>{const p=Math.round(b.realized/b.planned*100);return `<article class="entity-card"><span class="badge ${p>90?'danger':p>70?'warning':'success'}">${p}% utilizado</span><h3 style="margin-top:12px">${esc(b.name)}</h3><p>${esc(b.costCenter)} · Responsável: ${esc(b.owner)}</p><div class="progress-row"><div class="progress-meta"><span>Realizado</span><strong>${money(b.realized)}</strong></div><div class="progress-track ${p>80?'coral':''}"><i style="width:${Math.min(p,100)}%"></i></div></div><div class="entity-meta"><div><small>Planejado</small><strong>${money(b.planned)}</strong></div><div><small>Comprometido</small><strong>${money(b.committed)}</strong></div></div>${canWriteFinance()?`<button class="btn btn-secondary btn-small" style="margin-top:12px" data-action="budget-edit" data-id="${b.id}">Editar orçamento</button>`:''}</article>`}).join('')}</div></div>`;
  }

  function renderFunds(){
    return `<div class="page">${pageTitle('RECURSOS COM FINALIDADE','Fundos e campanhas','Metas, arrecadação, prazo e conta vinculada para recursos restritos e campanhas.',canWriteFinance()?actionButton('new-fund','Novo fundo ou campanha'): '')}
      <div class="card-grid">${db.funds.map(f=>{const p=Math.round(f.raised/f.target*100);return `<article class="entity-card"><span class="badge ${statusClass(f.status)}">${esc(f.status)}</span><h3 style="margin-top:12px">${esc(f.name)}</h3><p>${esc(f.description)}</p><div class="progress-row"><div class="progress-meta"><span>${money(f.raised)} arrecadados</span><strong>${p}%</strong></div><div class="progress-track"><i style="width:${Math.min(p,100)}%"></i></div></div><div class="entity-meta"><div><small>Meta</small><strong>${money(f.target)}</strong></div><div><small>Prazo</small><strong>${dateBR(f.endDate)}</strong></div><div><small>Conta</small><strong>${esc(byId('accounts',f.accountId)?.name||'—')}</strong></div></div>${canWriteFinance()?`<button class="btn btn-secondary btn-small" style="margin-top:12px" data-action="fund-edit" data-id="${f.id}">Editar</button>`:''}</article>`}).join('')}</div></div>`;
  }

  function renderSuppliers(){
    const rows=db.suppliers.filter(s=>!state.query||normalize(`${s.name} ${s.document} ${s.category}`).includes(normalize(state.query)));
    return `<div class="page">${pageTitle('COMPRAS E CONTRATOS','Fornecedores','Cadastro fiscal, categoria, contato e histórico de relacionamento financeiro.',canWriteFinance()?actionButton('new-supplier','Novo fornecedor'): '')}
      <div class="workspace">${searchToolbar('Buscar fornecedor, CNPJ ou categoria')}<div class="data-table-wrap"><table class="data-table"><thead><tr><th>Fornecedor</th><th>Documento</th><th>Categoria</th><th>Contato</th><th>E-mail</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${esc(s.name)}</strong></td><td>${esc(s.document)}</td><td>${esc(s.category)}</td><td>${esc(s.contact)}</td><td>${esc(s.email||'—')}</td><td>${badge(s.status)}</td><td><div class="table-actions">${canWriteFinance()?`<button data-action="supplier-edit" data-id="${s.id}">${icon('i-edit')}</button><button data-action="supplier-delete" data-id="${s.id}">${icon('i-trash')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></div></div>`;
  }

  function renderApprovals(){
    const rows=db.approvals.filter(a=>state.tab==='all'||a.status===state.tab);
    return `<div class="page">${pageTitle('ALÇADAS E GOVERNANÇA','Aprovações','Fluxo de decisão para despesas, contas e alterações orçamentárias.')}
      <div class="metrics-grid">${metric('Pendentes',db.approvals.filter(a=>a.status==='Pendente').length,'i-shield','Aguardando decisão','coral')}${metric('Valor pendente',money(sum(db.approvals.filter(a=>a.status==='Pendente'),a=>a.amount)),'i-wallet','Montante sob análise','gold')}${metric('Aprovadas',db.approvals.filter(a=>a.status==='Aprovado').length,'i-check','Decisões positivas')}${metric('Reprovadas',db.approvals.filter(a=>a.status==='Reprovado').length,'i-close','Solicitações negadas','navy')}</div>
      <div class="workspace"><div class="workspace-toolbar"><div class="segmented"><button data-filter-tab="all" class="${state.tab==='all'?'active':''}">Todas</button><button data-filter-tab="Pendente" class="${state.tab==='Pendente'?'active':''}">Pendentes</button><button data-filter-tab="Aprovado" class="${state.tab==='Aprovado'?'active':''}">Aprovadas</button><button data-filter-tab="Reprovado" class="${state.tab==='Reprovado'?'active':''}">Reprovadas</button></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Solicitação</th><th>Tipo</th><th>Solicitante</th><th>Aprovador</th><th>Valor</th><th>Status</th><th>Ações</th></tr></thead><tbody>${rows.map(a=>`<tr><td><strong>${esc(a.description)}</strong><small>${dateBR(a.requestedAt)} · ${esc(a.notes)}</small></td><td>${esc(a.kind)}</td><td>${esc(a.requester)}</td><td>${esc(a.approver)}</td><td>${money(a.amount)}</td><td>${badge(a.status)}</td><td><div class="table-actions">${canWriteFinance()&&a.status==='Pendente'?`<button data-action="approval-approve" data-id="${a.id}" title="Aprovar">${icon('i-check')}</button><button data-action="approval-reject" data-id="${a.id}" title="Reprovar">${icon('i-close')}</button>`:''}</div></td></tr>`).join('')}</tbody></table></div></div></div>`;
  }

  function reportRows(){let rows=confirmedTransactions();const start=state.reportStart||`${new Date().getFullYear()}-01-01`,end=state.reportEnd||todayISO();rows=rows.filter(t=>t.date>=start&&t.date<=end);if(state.reportAccount!=='all')rows=rows.filter(t=>t.accountId===state.reportAccount);return rows;}
  function renderReports(){
    if(!state.reportStart)state.reportStart=`${new Date().getFullYear()}-01-01`;if(!state.reportEnd)state.reportEnd=todayISO();const rows=reportRows(),income=sum(rows.filter(t=>t.type==='entrada'),t=>t.amount),expense=sum(rows.filter(t=>t.type==='saida'),t=>t.amount),balance=income-expense,groups=groupBy(rows.filter(t=>t.type==='saida'),'category');
    return `<div class="page">${pageTitle('PRESTAÇÃO DE CONTAS','Relatórios financeiros','Demonstrativos por período, conta, categoria e centro de custo.',`<button class="btn btn-secondary" data-action="report-print">${icon('i-print')}Imprimir</button><button class="btn btn-primary" data-action="report-export">${icon('i-download')}Exportar CSV</button>`)}
      <div class="filter-grid"><label><span>Data inicial</span><input data-report-filter="reportStart" type="date" value="${state.reportStart}"></label><label><span>Data final</span><input data-report-filter="reportEnd" type="date" value="${state.reportEnd}"></label><label><span>Conta</span><select data-report-filter="reportAccount"><option value="all">Todas as contas</option>${db.accounts.map(a=>`<option value="${a.id}" ${state.reportAccount===a.id?'selected':''}>${esc(a.name)}</option>`).join('')}</select></label></div>
      <div class="metrics-grid">${metric('Entradas',money(income),'i-arrow-up','Período filtrado')}${metric('Saídas',money(expense),'i-arrow-down','Período filtrado','coral')}${metric('Resultado',money(balance),'i-chart','Superávit / déficit',balance<0?'coral':'')}${metric('Lançamentos',rows.length,'i-receipt','Movimentações confirmadas','gold')}</div>
      <div class="dashboard-grid"><article class="panel span-5"><div class="panel-head"><div><span class="panel-kicker">DESPESAS</span><h2>Por categoria</h2></div></div>${categoryBars(groups)}</article><article class="panel span-7"><div class="panel-head"><div><span class="panel-kicker">LIVRO-CAIXA</span><h2>Demonstrativo</h2></div></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Descrição</th><th>Conta</th><th>Valor</th></tr></thead><tbody>${rows.sort((a,b)=>b.date.localeCompare(a.date)).map(t=>`<tr><td>${dateBR(t.date)}</td><td>${esc(t.description)}<small>${esc(t.category)} · ${esc(t.costCenter)}</small></td><td>${esc(byId('accounts',t.accountId)?.name||'—')}</td><td class="${t.type==='entrada'?'amount-in':'amount-out'}">${t.type==='entrada'?'+':'−'} ${money(t.amount)}</td></tr>`).join('')}</tbody></table></div></article></div></div>`;
  }
  function groupBy(rows,key){const map={};rows.forEach(r=>map[r[key]]=(map[r[key]]||0)+Number(r.amount));return Object.entries(map).sort((a,b)=>b[1]-a[1]);}
  function categoryBars(groups){const max=Math.max(...groups.map(g=>g[1]),1);return `<div>${groups.map(([label,value])=>`<div class="progress-row"><div class="progress-meta"><span>${esc(label)}</span><strong>${money(value)}</strong></div><div class="progress-track coral"><i style="width:${value/max*100}%"></i></div></div>`).join('')||emptyState('i-chart','Sem dados','Não há despesas no período.')}</div>`;}

  function renderFinanceSettings(){
    return `<div class="page">${pageTitle('PARÂMETROS FINANCEIROS','Configurações financeiras','Contas, categorias, centros de custo e políticas de operação.')}
      <div class="dashboard-grid"><article class="panel span-6"><div class="panel-head"><div><span class="panel-kicker">CONTAS</span><h2>Contas financeiras</h2></div>${canWriteFinance()?`<button class="btn btn-primary btn-small" data-action="new-account">Nova conta</button>`:''}</div><div class="settings-list">${db.accounts.map(a=>`<div class="settings-item"><div><strong>${esc(a.name)}</strong><small>${esc(a.bank)} · ${esc(a.type)} · ${money(accountBalance(a.id))}</small></div>${badge(a.active?'Ativa':'Inativa')}</div>`).join('')}</div></article><article class="panel span-6"><div class="panel-head"><div><span class="panel-kicker">CENTROS DE CUSTO</span><h2>Estrutura utilizada</h2></div></div><div class="settings-list">${[...new Set(db.transactions.map(t=>t.costCenter).concat(db.budgets.map(b=>b.costCenter)))].sort().map(c=>`<div class="settings-item"><div><strong>${esc(c)}</strong><small>${db.transactions.filter(t=>t.costCenter===c).length} movimentação(ões)</small></div></div>`).join('')}</div></article></div></div>`;
  }

  function topValue(rows,key){const counts={};rows.forEach(r=>counts[r[key]]=(counts[r[key]]||0)+1);return Object.entries(counts).sort((a,b)=>b[1]-a[1])[0]?.[0]||'—';}
  function addDays(days){const d=new Date();d.setDate(d.getDate()+days);return d.toISOString().slice(0,10)}

  function performAction(action,id,value){
    const modalMap={
      'new-member':()=>openMember(), 'member-edit':()=>openMember(id), 'member-view':()=>viewMember(id), 'new-visitor':()=>openVisitor(), 'visitor-edit':()=>openVisitor(id),
      'new-care':()=>openCare(), 'care-edit':()=>openCare(id), 'new-ministry':()=>openMinistry(), 'ministry-edit':()=>openMinistry(id), 'ministry-view':()=>viewMinistry(id),
      'new-team':()=>openTeam(), 'new-shift':()=>openShift(), 'shift-edit':()=>openShift(id), 'new-event':()=>openEvent(id||'',value), 'event-edit':()=>openEvent(id),
      'new-attendance':()=>openAttendance(), 'new-member-transfer':()=>openMemberTransfer(), 'member-transfer-edit':()=>openMemberTransfer(id), 'new-asset':()=>openAsset(), 'asset-edit':()=>openAsset(id), 'new-document':()=>openDocument(), 'document-edit':()=>openDocument(id), 'library-issue':()=>openLibraryIssue(id,value),
      'new-announcement':()=>openAnnouncement(), 'announcement-edit':()=>openAnnouncement(id), 'new-user':()=>openUser(), 'user-edit':()=>openUser(id), 'cloud-sync-settings':()=>openCloudSyncSettings(),
      'new-income':()=>openTransaction('entrada'), 'new-expense':()=>openTransaction('saida'), 'cash-new-income':()=>openTransaction('entrada','',id), 'cash-new-expense':()=>openTransaction('saida','',id), 'transaction-edit':()=>openTransaction('',id), 'new-contribution':()=>openContribution(), 'contribution-edit':()=>openContribution(id),
      'new-bill':()=>openBill(), 'bill-edit':()=>openBill(id), 'new-account':()=>openAccount(), 'account-edit':()=>openAccount(id), 'new-reconciliation':()=>openReconciliation(), 'credit-installment-settings':()=>openCreditInstallmentSettings(), 'payment-integration-settings':()=>openPaymentIntegrationSettings(), 'treasury-notification-settings':()=>openTreasuryNotificationSettings(), 'treasury-force-close':()=>openTreasuryForceClose(), 'treasury-operator-new':()=>openTreasuryOperator(), 'treasury-operator-edit':()=>openTreasuryOperator(id),
      'cash-open':()=>openCashOpening(), 'cash-reinforcement':()=>openCashAdjustment(id,'reforco'), 'cash-withdrawal':()=>openCashAdjustment(id,'sangria'), 'cash-close':()=>openCashClosing(id), 'new-budget':()=>openBudget(), 'budget-edit':()=>openBudget(id), 'new-fund':()=>openFund(), 'fund-edit':()=>openFund(id), 'new-supplier':()=>openSupplier(), 'supplier-edit':()=>openSupplier(id)
    }; if(modalMap[action]){modalMap[action]();return;}
    if(action==='cloud-sync-test'){cloudSyncTest();return;}
    if(action==='cloud-sync-publish'){cloudSyncPublish();return;}
    if(action==='cloud-sync-pull'){cloudSyncPull();return;}
    if(action==='evangelization-open'){openEvangelizationLibrary();return;}
    if(action==='evangelization-new'){openEvangelismDesign(id);return;}
    if(action==='evangelization-edit'){const x=(db.evangelismDesigns||[]).find(item=>item.id===id);if(x)openEvangelismDesign(x.templateId,id);return;}
    if(action==='evangelization-print'){printEvangelismDesign(id);return;}
    if(action==='evangelization-delete'){deleteRecord('evangelismDesigns',id,'Material de evangelização excluído');setTimeout(openEvangelizationLibrary,50);return;}
    if(action==='church-delete'){deleteChurch(id);return;}
    if(action==='member-transfer-view'){viewMemberTransfer(id);return;}
    if(action==='member-transfer-print'){printMemberTransfer(id);return;}
    if(action==='member-transfer-delete'){deleteRecord('memberTransfers',id,'Transferência excluída');return;}
    if(action==='library-preview'){previewIssuedDocument(id);return;}
    if(action==='library-print'){printIssuedDocument(id);return;}
    if(action==='library-delete'){deleteRecord('issuedDocuments',id,'Documento excluído');return;}
    if(action==='open-treasury-login'){ audit('Solicitou abertura de caixa','Acesso à autenticação interna da Tesouraria e Caixa','finance'); if(window.santuarioDesktop?.isDesktop&&window.santuarioDesktop?.openCashWindow){window.santuarioDesktop.openCashWindow('tesouraria-login.html');showToast('Caixa aberto em janela separada','A Tesouraria e Caixa foi iniciada em uma janela própria com monitoramento operacional.','success');}else{window.open('tesouraria-login.html','santuario-caixa','width=1450,height=900');} return; }
    if(action==='treasury-operator-toggle'){toggleTreasuryOperator(id);return;}
    if(action==='treasury-report-open'){window.open(`tesouraria-extrato.html?report=${encodeURIComponent(id)}`,'_blank');return;}
    if(action==='member-delete')deleteRecord('members',id,'Pessoa excluída');
    if(action==='care-complete')updateStatus('careCases',id,'Concluído','Acompanhamento concluído');
    if(action==='shift-toggle')toggleShift(id);
    if(action==='calendar-prev'||action==='calendar-next'){state.month=new Date(state.month);state.month.setMonth(state.month.getMonth()+(action==='calendar-next'?1:-1));renderPage();}
    if(action==='asset-delete')deleteRecord('assets',id,'Patrimônio excluído');
    if(action==='document-delete')deleteRecord('documents',id,'Documento excluído');
    if(action==='announcement-delete')deleteRecord('announcements',id,'Comunicado excluído');
    if(action==='user-toggle')toggleUser(id);
    if(action==='backup-export')exportBackup(); if(action==='demo-reset')resetDemo();
    if(action==='transaction-delete')deleteTransaction(id);
    if(action==='transaction-receipt')printTransaction(id); if(action==='cash-print')printCashClosing(id); if(action==='contribution-receipt')printContribution(id);
    if(action==='transactions-export')exportTransactions(); if(action==='bill-delete')deleteRecord('bills',id,'Conta excluída'); if(action==='bill-settle')settleBill(id);
    if(action==='supplier-delete')deleteRecord('suppliers',id,'Fornecedor excluído');
    if(action==='approval-approve')decideApproval(id,'Aprovado'); if(action==='approval-reject')decideApproval(id,'Reprovado');
    if(action==='report-print')window.print();if(action==='report-export')exportReport();
  }

  function openModal({eyebrow='',title='',subtitle='',body='',wide=false}){ $('#modalEyebrow').textContent=eyebrow;$('#modalTitle').textContent=title;$('#modalSubtitle').textContent=subtitle;$('#modalBody').innerHTML=body;$('#appModal').classList.toggle('wide',wide);$('#modalBackdrop').hidden=false;setTimeout(()=>$('#modalBody input:not([type=hidden]),#modalBody select')?.focus(),50); }
  function closeModal(){ $('#modalBackdrop').hidden=true;$('#modalBody').innerHTML=''; }
  const options=(rows,value='',label='name',blank='Selecione')=>`<option value="">${blank}</option>${rows.map(r=>`<option value="${r.id}" ${r.id===value?'selected':''}>${esc(r[label])}</option>`).join('')}`;
  const textField=(name,label,value='',type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
  const selectField=(name,label,values,value='',extra='')=>`<label class="field"><span>${label}</span><select name="${name}" ${extra}>${values.map(v=>{const val=Array.isArray(v)?v[0]:v,lab=Array.isArray(v)?v[1]:v;return `<option value="${esc(val)}" ${val===value?'selected':''}>${esc(lab)}</option>`}).join('')}</select></label>`;
  const modalActions=()=>`<div class="form-actions"><button type="button" class="btn btn-secondary" data-action="modal-close">Cancelar</button><button class="btn btn-primary">Salvar</button></div>`;


  const mediaPreview=(value,label='Imagem')=>value?`<img src="${esc(value)}" alt="${esc(label)}">`:`<span class="media-upload-placeholder">${icon('i-image')}<b>Adicionar imagem</b><small>JPG, PNG ou WEBP</small></span>`;
  function imageUploadField(name,label,value='',aspect='square',hint='Selecione uma imagem e ajuste o enquadramento antes de salvar.'){
    return `<div class="field span-2 media-upload-field" data-media-upload data-aspect="${aspect}"><span>${esc(label)}</span><div class="media-upload-card ${value?'has-image':''}"><button type="button" class="media-upload-preview ${aspect}" data-media-preview-action aria-label="${value?'Ajustar':'Selecionar'} ${esc(label.toLowerCase())}">${mediaPreview(value,label)}</button><div class="media-upload-copy"><strong>${value?'Imagem adicionada':'Nenhuma imagem adicionada'}</strong><p>${esc(hint)}</p><div class="media-upload-actions"><button type="button" class="btn btn-secondary btn-small" data-media-pick>${icon('i-image')}${value?'Substituir imagem':'Escolher imagem'}</button><button type="button" class="btn btn-ghost btn-small" data-media-edit ${value?'':'hidden'}>${icon('i-edit')}Ajustar enquadramento</button><button type="button" class="btn btn-ghost btn-small" data-media-remove ${value?'':'hidden'}>${icon('i-trash')}Remover</button></div></div><input type="hidden" name="${name}" value="${esc(value)}"><input type="file" data-media-file accept="image/jpeg,image/png,image/webp" hidden></div></div>`;
  }
  function updateMediaUploader(uploader,value){
    if(!uploader)return;
    const normalized=value||'',hidden=uploader.querySelector('input[type="hidden"]');
    if(hidden){hidden.value=normalized;hidden.setAttribute('value',normalized);hidden.dispatchEvent(new Event('input',{bubbles:true}));hidden.dispatchEvent(new Event('change',{bubbles:true}));}
    uploader.dataset.mediaDirty='true';
    const card=uploader.querySelector('.media-upload-card'),preview=uploader.querySelector('.media-upload-preview'),copy=card?.querySelector('.media-upload-copy strong'),pick=card?.querySelector('.media-upload-actions [data-media-pick]'),edit=card?.querySelector('[data-media-edit]'),remove=card?.querySelector('[data-media-remove]');
    card?.classList.toggle('has-image',Boolean(normalized));
    if(preview){preview.innerHTML=mediaPreview(normalized,uploader.querySelector(':scope > span')?.textContent||'Imagem');preview.setAttribute('aria-label',`${normalized?'Ajustar':'Selecionar'} ${String(uploader.querySelector(':scope > span')?.textContent||'imagem').toLowerCase()}`);}
    if(copy)copy.textContent=normalized?'Imagem adicionada':'Nenhuma imagem adicionada';
    if(pick)pick.innerHTML=`${icon('i-image')}${normalized?'Substituir imagem':'Escolher imagem'}`;
    if(edit)edit.hidden=!normalized;if(remove)remove.hidden=!normalized;
  }
  let imageEditorState=null;
  function openImageEditor(source,uploader){
    if(!source||!uploader)return;
    const loadSource=src=>{const image=new Image();image.onload=()=>mountImageEditor(image,src,uploader);image.onerror=()=>showToast('Imagem inválida','Não foi possível abrir este arquivo.','error');image.src=src;};
    if(typeof source==='string'){loadSource(source);return;}
    const file=source;if(!/^image\/(jpeg|png|webp)$/i.test(file.type)){showToast('Formato não suportado','Use uma imagem JPG, PNG ou WEBP.','error');return;}if(file.size>20*1024*1024){showToast('Imagem muito grande','Escolha um arquivo de até 20 MB.','error');return;}
    const reader=new FileReader();reader.onload=()=>loadSource(reader.result);reader.readAsDataURL(file);
  }
  function imageAspectRatio(aspect){return aspect==='wide'?16/9:aspect==='portrait'?3/4:1;}
  function mountImageEditor(image,src,uploader){
    closeImageEditor();
    const raw=uploader.dataset.aspect||'square',aspect=['wide','portrait','square'].includes(raw)?raw:'square';
    imageEditorState={uploader,image,src,aspect,fitMode:'cover',zoom:1,offsetX:0,offsetY:0,rotation:0,flipX:1,flipY:1,cropWidthRatio:.82,cropHeightRatio:.82,baseScale:0,dragging:false,resizing:false,startX:0,startY:0,startOffsetX:0,startOffsetY:0};
    document.body.insertAdjacentHTML('beforeend',`<div id="imageEditorBackdrop" class="image-editor-backdrop"><section class="image-editor-dialog free-editor" role="dialog" aria-modal="true"><header><div><span class="panel-kicker">EDITOR LIVRE DE IMAGEM</span><h2>Definir enquadramento de corte</h2><p>A imagem mantém sua proporção. Redimensione a moldura de corte em largura e altura, depois mova e amplie a imagem por trás dela.</p></div><button type="button" class="icon-button bordered" data-image-editor-close>${icon('i-close')}</button></header><div class="image-editor-workspace"><div class="image-editor-stage free" data-image-editor-stage><img src="${esc(src)}" alt="Prévia da imagem"><div class="image-editor-crop ${aspect}" data-image-editor-crop><span class="crop-handle tl" data-image-editor-crop-handle="tl"></span><span class="crop-handle t" data-image-editor-crop-handle="t"></span><span class="crop-handle tr" data-image-editor-crop-handle="tr"></span><span class="crop-handle r" data-image-editor-crop-handle="r"></span><span class="crop-handle br" data-image-editor-crop-handle="br"></span><span class="crop-handle b" data-image-editor-crop-handle="b"></span><span class="crop-handle bl" data-image-editor-crop-handle="bl"></span><span class="crop-handle l" data-image-editor-crop-handle="l"></span></div></div><aside class="image-editor-sidebar"><div class="image-editor-control"><span class="image-editor-control-title">Ajuste da imagem</span><div class="image-editor-segmented"><button type="button" class="active" data-image-editor-fit="cover">Preencher recorte</button><button type="button" data-image-editor-fit="contain">Mostrar inteira</button></div><small>Esses botões ajustam a imagem à moldura atual sem deformá-la.</small></div><div class="image-editor-control"><div class="image-editor-control-row"><span class="image-editor-control-title">Zoom da imagem</span><output data-image-editor-zoom-label>100%</output></div><div class="image-editor-zoom-row"><button type="button" class="image-editor-round-button" data-image-editor-zoom-step="-0.1">−</button><input type="range" min="0.03" max="15" value="1" step="0.01" data-image-editor-zoom><button type="button" class="image-editor-round-button" data-image-editor-zoom-step="0.1">+</button></div><small>A imagem cresce ou diminui mantendo a proporção original.</small></div><div class="image-editor-control image-editor-crop-dimensions"><div class="image-editor-control-row"><span class="image-editor-control-title">Tamanho do recorte</span><strong>moldura</strong></div><label class="image-editor-dimension-row"><span>Largura</span><input type="range" min="0.12" max="0.96" value="0.82" step="0.01" data-image-editor-crop-width><output data-image-editor-crop-width-label>82%</output></label><label class="image-editor-dimension-row"><span>Altura</span><input type="range" min="0.12" max="0.96" value="0.82" step="0.01" data-image-editor-crop-height><output data-image-editor-crop-height-label>82%</output></label><small>Largura e altura são totalmente independentes. Use os puxadores laterais para alterar somente um eixo ou os cantos para alterar os dois.</small></div><div class="image-editor-control"><div class="image-editor-control-row"><span class="image-editor-control-title">Rotação da imagem</span><output data-image-editor-rotation-label>0°</output></div><input type="range" min="-180" max="180" value="0" step="1" data-image-editor-rotation><div class="image-editor-mini-actions"><button type="button" data-image-editor-rotate-step="-90">↶ 90°</button><button type="button" data-image-editor-rotate-step="90">↷ 90°</button><button type="button" data-image-editor-flip="x">Espelhar ↔</button><button type="button" data-image-editor-flip="y">Espelhar ↕</button></div></div><button type="button" class="btn btn-ghost image-editor-reset" data-image-editor-reset>${icon('i-refresh')}Restaurar tudo</button><div class="image-editor-tip">${icon('i-hand')}<span>Arraste a imagem para reposicionar. Laterais alteram um único eixo do recorte; cantos alteram os dois. A imagem não será esticada nem reajustada automaticamente.</span></div></aside></div><footer><button type="button" class="btn btn-secondary" data-image-editor-close>Cancelar</button><button type="button" class="btn btn-primary" data-image-editor-save>${icon('i-check')}Recortar e usar</button></footer></section></div>`);
    const stage=document.querySelector('[data-image-editor-stage]');imageEditorState.stage=stage;imageEditorState.img=stage.querySelector('img');imageEditorState.crop=stage.querySelector('[data-image-editor-crop]');imageEditorState.draw=drawImageEditor;
    requestAnimationFrame(()=>{initializeCropRatios();setImageEditorFit('cover');bindFreeImageEditor();});
  }
  function initializeCropRatios(){const s=imageEditorState;if(!s?.stage)return;const rect=s.stage.getBoundingClientRect(),ratio=imageAspectRatio(s.aspect),maxW=rect.width*.82,maxH=rect.height*.82;let width=maxW,height=width/ratio;if(height>maxH){height=maxH;width=height*ratio;}s.cropWidthRatio=width/rect.width;s.cropHeightRatio=height/rect.height;syncCropControls();}
  function cropRectForEditor(){const s=imageEditorState,stage=s?.stage;if(!s||!stage)return {left:0,top:0,width:1,height:1};const rect=stage.getBoundingClientRect(),width=Math.max(70,Math.min(rect.width*.96,rect.width*s.cropWidthRatio)),height=Math.max(70,Math.min(rect.height*.96,rect.height*s.cropHeightRatio));return {left:(rect.width-width)/2,top:(rect.height-height)/2,width,height};}
  function drawImageEditor(){const s=imageEditorState;if(!s?.stage)return;const crop=cropRectForEditor();s.crop.style.left=`${crop.left}px`;s.crop.style.top=`${crop.top}px`;s.crop.style.width=`${crop.width}px`;s.crop.style.height=`${crop.height}px`;if(!s.baseScale){s.baseScale=Math.max(crop.width/s.image.naturalWidth,crop.height/s.image.naturalHeight);}const scale=s.baseScale*s.zoom;s.displayScale=scale;s.img.style.width=`${s.image.naturalWidth*scale}px`;s.img.style.height=`${s.image.naturalHeight*scale}px`;s.img.style.transform=`translate(-50%,-50%) translate(${s.offsetX}px,${s.offsetY}px) rotate(${s.rotation}deg) scale(${s.flipX},${s.flipY})`;}
  function syncCropControls(){const s=imageEditorState;if(!s)return;const w=document.querySelector('[data-image-editor-crop-width]'),h=document.querySelector('[data-image-editor-crop-height]');if(w)w.value=String(s.cropWidthRatio);if(h)h.value=String(s.cropHeightRatio);updateImageEditorLabels();}
  function bindFreeImageEditor(){const s=imageEditorState,stage=s.stage;let resizeHandle='';const startMove=(x,y)=>{s.dragging=true;s.startX=x;s.startY=y;s.startOffsetX=s.offsetX;s.startOffsetY=s.offsetY;stage.classList.add('dragging')};const moveImage=(x,y)=>{if(!s.dragging)return;s.offsetX=s.startOffsetX+(x-s.startX);s.offsetY=s.startOffsetY+(y-s.startY);s.draw()};const startResize=(handle,x,y)=>{const crop=cropRectForEditor(),rect=stage.getBoundingClientRect();s.resizing=true;resizeHandle=handle;s.resizeStartX=x;s.resizeStartY=y;s.resizeStartWidth=crop.width;s.resizeStartHeight=crop.height;s.resizeStageWidth=rect.width;s.resizeStageHeight=rect.height;stage.classList.add('resizing')};const resize=(x,y)=>{if(!s.resizing)return;const dx=x-s.resizeStartX,dy=y-s.resizeStartY,min=70,maxW=s.resizeStageWidth*.96,maxH=s.resizeStageHeight*.96;let width=s.resizeStartWidth,height=s.resizeStartHeight;if(resizeHandle.includes('r'))width=Math.max(min,Math.min(maxW,s.resizeStartWidth+dx*2));if(resizeHandle.includes('l'))width=Math.max(min,Math.min(maxW,s.resizeStartWidth-dx*2));if(resizeHandle.includes('b'))height=Math.max(min,Math.min(maxH,s.resizeStartHeight+dy*2));if(resizeHandle.includes('t'))height=Math.max(min,Math.min(maxH,s.resizeStartHeight-dy*2));s.cropWidthRatio=width/s.resizeStageWidth;s.cropHeightRatio=height/s.resizeStageHeight;syncCropControls();s.draw()};const stop=()=>{s.dragging=false;s.resizing=false;resizeHandle='';stage.classList.remove('dragging','resizing')};stage.addEventListener('pointerdown',e=>{const handle=e.target.closest?.('[data-image-editor-crop-handle]');e.preventDefault();stage.setPointerCapture?.(e.pointerId);if(handle){e.stopPropagation();startResize(handle.dataset.imageEditorCropHandle,e.clientX,e.clientY);}else startMove(e.clientX,e.clientY)});stage.addEventListener('pointermove',e=>{if(s.resizing)resize(e.clientX,e.clientY);else moveImage(e.clientX,e.clientY)});stage.addEventListener('pointerup',stop);stage.addEventListener('pointercancel',stop);stage.addEventListener('wheel',e=>{e.preventDefault();s.zoom=Math.max(.03,Math.min(15,s.zoom*(e.deltaY<0?1.08:.92)));const slider=document.querySelector('[data-image-editor-zoom]');if(slider)slider.value=String(s.zoom);updateImageEditorLabels();s.draw()},{passive:false});}
  function updateImageEditorLabels(){const s=imageEditorState;if(!s)return;const z=document.querySelector('[data-image-editor-zoom-label]'),w=document.querySelector('[data-image-editor-crop-width-label]'),h=document.querySelector('[data-image-editor-crop-height-label]'),r=document.querySelector('[data-image-editor-rotation-label]');if(z)z.textContent=`${Math.round(s.zoom*100)}%`;if(w)w.textContent=`${Math.round(s.cropWidthRatio*100)}%`;if(h)h.textContent=`${Math.round(s.cropHeightRatio*100)}%`;if(r)r.textContent=`${Math.round(s.rotation)}°`;}
  function setImageEditorFit(mode){const s=imageEditorState;if(!s||!['cover','contain'].includes(mode))return;const crop=cropRectForEditor();s.fitMode=mode;s.baseScale=mode==='contain'?Math.min(crop.width/s.image.naturalWidth,crop.height/s.image.naturalHeight):Math.max(crop.width/s.image.naturalWidth,crop.height/s.image.naturalHeight);s.zoom=1;s.offsetX=0;s.offsetY=0;document.querySelectorAll('[data-image-editor-fit]').forEach(button=>button.classList.toggle('active',button.dataset.imageEditorFit===mode));const slider=document.querySelector('[data-image-editor-zoom]');if(slider)slider.value='1';updateImageEditorLabels();s.draw?.();}
  function stepImageEditorZoom(step){const s=imageEditorState;if(!s)return;s.zoom=Math.max(.03,Math.min(15,s.zoom+step));const slider=document.querySelector('[data-image-editor-zoom]');if(slider)slider.value=String(s.zoom);updateImageEditorLabels();s.draw?.();}
  function resetImageEditor(){const s=imageEditorState;if(!s)return;s.fitMode='cover';s.baseScale=0;s.zoom=1;s.offsetX=0;s.offsetY=0;s.rotation=0;s.flipX=1;s.flipY=1;document.querySelectorAll('[data-image-editor-fit]').forEach(button=>button.classList.toggle('active',button.dataset.imageEditorFit==='cover'));document.querySelectorAll('[data-image-editor-flip]').forEach(button=>button.classList.remove('active'));const rotation=document.querySelector('[data-image-editor-rotation]');if(rotation)rotation.value='0';const zoom=document.querySelector('[data-image-editor-zoom]');if(zoom)zoom.value='1';initializeCropRatios();updateImageEditorLabels();s.draw?.();}
  function closeImageEditor(){document.getElementById('imageEditorBackdrop')?.remove();imageEditorState=null;}
  function saveImageEditor(){const s=imageEditorState;if(!s?.stage)return;const stageRect=s.stage.getBoundingClientRect(),crop=cropRectForEditor(),cropRatio=crop.width/crop.height,pixelRatio=2,stageCanvas=document.createElement('canvas');stageCanvas.width=Math.round(stageRect.width*pixelRatio);stageCanvas.height=Math.round(stageRect.height*pixelRatio);const sc=stageCanvas.getContext('2d');sc.fillStyle='#ffffff';sc.fillRect(0,0,stageCanvas.width,stageCanvas.height);sc.imageSmoothingEnabled=true;sc.imageSmoothingQuality='high';sc.save();sc.scale(pixelRatio,pixelRatio);sc.translate(stageRect.width/2+s.offsetX,stageRect.height/2+s.offsetY);sc.rotate(s.rotation*Math.PI/180);sc.scale((s.displayScale||1)*s.flipX,(s.displayScale||1)*s.flipY);sc.drawImage(s.image,-s.image.naturalWidth/2,-s.image.naturalHeight/2);sc.restore();let outW,outH;if(cropRatio>=1){outW=1000;outH=Math.max(1,Math.round(outW/cropRatio));}else{outH=1000;outW=Math.max(1,Math.round(outH*cropRatio));}const out=document.createElement('canvas');out.width=outW;out.height=outH;const ctx=out.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,outW,outH);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(stageCanvas,crop.left*pixelRatio,crop.top*pixelRatio,crop.width*pixelRatio,crop.height*pixelRatio,0,0,outW,outH);const value=out.toDataURL('image/jpeg',.84);const uploader=s.uploader;updateMediaUploader(uploader,value);closeImageEditor();showToast('Recorte aplicado','O novo recorte já está no formulário. Clique em Salvar para gravar a alteração.');}
  function handleImageDrop(event){const uploader=event.target.closest?.('[data-media-upload]');if(!uploader)return;event.preventDefault();uploader.classList.remove('drag-over');const file=event.dataTransfer?.files?.[0];if(file)openImageEditor(file,uploader);}

  function openMemberTransfer(id=''){
    const x=byId('memberTransfers',id)||{},protocol=x.protocol||`TRF-${new Date().getFullYear()}-${String((db.memberTransfers||[]).length+1).padStart(4,'0')}`;
    openModal({eyebrow:'BIBLIOTECA',title:id?'Editar transferência':'Nova transferência de membro',subtitle:'Formalize a entrada ou saída e gere a carta institucional correspondente.',wide:true,body:`<form data-form="member-transfer" data-id="${id}" class="form-grid"><label class="field span-2"><span>Membro</span><select name="memberId" required>${options(db.members,x.memberId,'name')}</select></label>${textField('protocol','Protocolo',protocol,'text','required')}${selectField('direction','Tipo de movimentação',[[ 'saida','Transferência de saída'],['entrada','Recebimento de membro']],x.direction||'saida')}${textField('date','Data',x.date||todayISO(),'date','required')}${textField('otherChurch','Igreja de origem ou destino',x.otherChurch||'','text','required')}${textField('city','Cidade / UF',x.city||'')}${textField('responsible','Responsável',x.responsible||currentUser.name)}${selectField('status','Status',['Em andamento','Concluída','Cancelada'],x.status||'Em andamento')}${textField('book','Livro',x.book||'03')}${textField('folio','Folha',x.folio||'27')}${textField('term','Termo',x.term||'021')}<label class="field span-2"><span>Motivo e observações</span><textarea name="notes">${esc(x.notes||'')}</textarea></label>${modalActions()}</form>`});
  }
  function transferMemberNumber(member){return member?.memberNumber||`MEM-${String(Math.max(1,db.members.findIndex(item=>item.id===member?.id)+1)).padStart(5,'0')}`;}
  function institutionalLogo(){return `<img class="institutional-logo" src="assets/images/adoradores-logo-documental.png" alt="Logo Adoradores de Cristo">`;}
  function institutionalContact(church){const locality=[church.city,church.state].filter(Boolean).join(' - ');return `<div class="institutional-contact">${church.address?`<span>${esc(church.address)}${locality?` · ${esc(locality)}`:''}</span>`:''}${church.phone||church.email?`<span>${church.phone?`Telefone: ${esc(church.phone)}`:''}${church.phone&&church.email?' · ':''}${church.email?`E-mail: ${esc(church.email)}`:''}</span>`:''}${church.cnpj?`<span>CNPJ: ${esc(church.cnpj)}</span>`:''}</div>`;}
  function formalHeader(church){return `<header class="formal-letterhead">${institutionalLogo()}<h2>${esc(church.legalName||church.name)}</h2>${institutionalContact(church)}<div class="formal-gold-rule"><i></i></div></header>`;}
  function formalSignatures(labels){return `<section class="formal-signatures">${labels.map(label=>`<div><span></span><strong>${esc(label)}</strong></div>`).join('')}</section>`;}
  function memberTransferMarkup(x){
    const church=activeChurch(),member=byId('members',x.memberId)||{name:x.memberName||'Membro'},destination=x.otherChurch||'Igreja / Congregação de destino',number=transferMemberNumber(member),date=dateBR(x.date,{day:'2-digit',month:'long',year:'numeric'}),origin=church.name;
    const directionOut=x.direction!=='entrada';
    const title=directionOut?'CARTA DE TRANSFERÊNCIA DE MEMBRO':'TERMO DE RECEBIMENTO DE MEMBRO';
    const destinationLabel=directionOut?'À Igreja / Congregação de destino':'Igreja / Congregação de origem';
    const body=directionOut?`<p>Pela presente, declaramos para os devidos fins que o(a) irmão(ã) <strong>${esc(member.name)}</strong>, portador(a) do cadastro de membro nº <strong>${esc(number)}</strong>, encontra-se em plena comunhão com esta igreja, tendo participado de nossas atividades eclesiásticas com testemunho cristão compatível com os princípios da fé.</p><p>Atendendo à solicitação apresentada, formalizamos sua transferência para a igreja ou congregação acima identificada, recomendando sua recepção e continuidade de vínculo cristão, rogando as bênçãos de Deus sobre sua caminhada espiritual.</p>`:`<p>Pela presente, registramos o recebimento do(a) irmão(ã) <strong>${esc(member.name)}</strong>, proveniente da igreja ou congregação acima identificada, para integração ao quadro de membros desta instituição.</p><p>O presente termo formaliza seu recebimento e início de acompanhamento eclesiástico nesta comunidade de fé.</p>`;
    const history=`<p>Conforme nossos registros, sua admissão ocorreu em ${dateBR(member.joinedAt,{day:'2-digit',month:'long',year:'numeric'})}, congregando na unidade ${esc(origin)}${member.ministryIds?.length?` e cooperando no ministério de ${esc(member.ministryIds.map(id=>byId('ministries',id)?.name).filter(Boolean).join(', '))}`:''}.</p>`;
    const registry=[x.book&&`livro ${esc(x.book)}`,x.folio&&`folha ${esc(x.folio)}`,x.term&&`termo ${esc(x.term)}`].filter(Boolean).join(', ');
    return `<div class="document-preview formal-preview"><article class="official-formal-document transfer-letter">${formalHeader(church)}<div class="formal-protocol">Carta nº ${esc(x.protocol)}</div><h1>${title}</h1><p class="formal-subtitle">Documento institucional</p><section class="formal-letter-meta"><p><b>Local e data:</b> ${esc(church.city||'')}${church.state?` - ${esc(church.state)}`:''}, ${date}</p><p><b>${destinationLabel}:</b><br><strong>${esc(destination)}</strong></p><p><b>Assunto:</b> ${directionOut?'Transferência de membresia':'Recebimento de membresia'}</p></section><section class="formal-body">${body}${history}<p>A presente carta é emitida para formalizar ${directionOut?'a transferência':'o recebimento'} e produzir seus efeitos na data de sua assinatura.${registry?` O registro encontra-se arquivado em ${registry}.`:''}</p>${x.notes?`<p>${esc(x.notes)}</p>`:''}</section>${formalSignatures(['Pastor Responsável','Secretário(a)',directionOut?'Membro / Transferido(a)':'Membro / Recebido(a)'])}<footer class="formal-footer"><p>Documento emitido eletronicamente pela Biblioteca Institucional.</p><div></div><em>Ora, vós sois o corpo de Cristo, e seus membros em particular. — 1 Coríntios 12:27</em></footer></article></div>`;
  }
  function viewMemberTransfer(id){const x=byId('memberTransfers',id);if(!x)return;openModal({eyebrow:'TRANSFERÊNCIA DE MEMBRO',title:x.protocol,subtitle:`${dateBR(x.date)} · ${x.direction==='saida'?'Saída':'Entrada'}`,wide:true,body:`${memberTransferMarkup(x)}<div class="form-actions preview-actions"><button class="btn btn-secondary" data-action="modal-close">Fechar</button><button class="btn btn-primary" data-action="member-transfer-print" data-id="${x.id}">${icon('i-print')}Imprimir / PDF</button></div>`});}
  function printMemberTransfer(id){
    const x=byId('memberTransfers',id);if(!x)return;const w=window.open('','_blank','width=900,height=1100');if(!w){showToast('Janela bloqueada','Permita pop-ups para imprimir a carta.','error');return;}const base=esc(new URL('.',location.href).href),markup=memberTransferMarkup(x);
    w.document.write(`<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><base href="${base}"><title>${esc(x.protocol)}</title><link rel="stylesheet" href="assets/css/app.css"><style>@page{size:A4 portrait;margin:0}html,body{margin:0;background:#fff}.print-wrap{width:210mm;height:297mm;margin:0}.document-preview{padding:0!important;background:#fff!important}.official-formal-document{width:210mm!important;height:297mm!important;max-width:none!important;box-shadow:none!important;margin:0!important}</style></head><body><div class="print-wrap">${markup}</div><script>Promise.all([...document.images].map(img=>img.complete?Promise.resolve():new Promise(r=>img.onload=img.onerror=r))).then(()=>setTimeout(()=>print(),120));<\/script></body></html>`);w.document.close();audit('Imprimiu carta de transferência',x.protocol,'library');
  }
  function openMember(id=''){const m=byId('members',id)||{};openModal({eyebrow:'PESSOAS',title:id?'Editar pessoa':'Nova pessoa',subtitle:'Cadastro administrativo e vínculo comunitário.',wide:true,body:`<form data-form="member" data-id="${id}" class="form-grid">${imageUploadField('image','Foto da pessoa',m.image||'','portrait','Ajuste o rosto no enquadramento. A imagem será otimizada automaticamente.')}${textField('name','Nome completo',m.name,'text','required')}${textField('cpf','CPF',m.cpf)}${textField('phone','Telefone',m.phone)}${textField('email','E-mail',m.email,'email')}${textField('birthDate','Nascimento',m.birthDate,'date')}${selectField('gender','Gênero',['Feminino','Masculino','Outro'],m.gender)}${selectField('maritalStatus','Estado civil',['Solteiro','Casado','Divorciado','Viúvo','União estável'],m.maritalStatus)}${selectField('type','Tipo',['Membro','Visitante'],m.type||'Membro')}${selectField('status','Situação',['Ativo','Em integração','Novo visitante','Afastado','Transferido'],m.status||'Ativo')}<label class="field"><span>Família</span><select name="familyId">${options(db.families,m.familyId,'name','Sem família')}</select></label>${textField('joinedAt','Data de entrada',m.joinedAt||todayISO(),'date')}${selectField('baptized','Batizado?',[['true','Sim'],['false','Não']],String(Boolean(m.baptized)))}${textField('baptismDate','Data do batismo',m.baptismDate,'date')}${textField('cep','CEP',m.cep||'')}<label class="field span-2"><span>Endereço</span><input name="address" value="${esc(m.address||'')}"></label>${textField('city','Cidade',m.city||activeChurch().city)}<label class="field span-2"><span>Observações</span><textarea name="notes">${esc(m.notes||'')}</textarea></label>${modalActions()}</form>`});}
