  function deleteChurch(id){
    const church=(db.churches||[]).find(item=>item.id===id);
    if(!church)return;
    if(!canAddChurch()){showToast('Acesso restrito','Somente Pastor Regional ou ADM Regional pode excluir filiais.','error');return;}
    if(church.type==='Matriz'||church.id===(db.churches||[])[0]?.id){showToast('Matriz protegida','A igreja matriz não pode ser excluída.','error');return;}
    const linkedUsers=(db.users||[]).filter(user=>(user.churchIds||[]).includes(id));
    const warning=linkedUsers.length?`

${linkedUsers.length} usuário(s) estão vinculados a esta igreja e ficarão sem igreja designada até serem reconfigurados.`:'';
    if(!confirm(`Excluir definitivamente ${church.name}? Todos os dados administrativos e financeiros desta igreja serão removidos.${warning}`))return;
    syncActiveChurchData();
    db.churches=db.churches.filter(item=>item.id!==id);
    if(db.branchData)delete db.branchData[id];
    db.users=(db.users||[]).map(user=>({...user,churchIds:(user.churchIds||[]).filter(churchId=>churchId!==id)}));
    if(currentChurchId===id){currentChurchId='';sessionStorage.removeItem(CHURCH_SESSION_KEY);}
    if(db.activeChurchDataId===id){db.activeChurchDataId='';const fallback=db.churches.find(item=>item.active!==false);if(fallback)activateChurchData(fallback.id);}
    audit('Excluiu uma igreja',church.name,'admin');saveData();closeModal();showChurchGate();showToast('Igreja excluída',church.name);
  }

