      Object.assign(church,{name,pastor:String(obj.pastor||'').trim(),legalName:obj.legalName||'',cnpj:obj.cnpj||'',phone:obj.phone||'',email:obj.email||'',cep:obj.cep||'',address:obj.address||'',city:obj.city||'',state:String(obj.state||'').toUpperCase().slice(0,2),type:church.type==='Matriz'?'Matriz':(obj.type||'Filial'),image:obj.image||'',colorKey:CHURCH_COLOR_PALETTE[colorKey]?colorKey:'cyan'});
